window.__LEDGER_UPD__ = {"version": "5.18", "html": "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover, maximum-scale=1, user-scalable=no\" />\n<meta name=\"theme-color\" content=\"#0b0e11\" />\n<title>人生账本 · Life Ledger<\/title>\n<style>\n  :root{\n    --bg:#0b0e11; --panel:#121518; --panel2:#191d22; --line:#1f242a;\n    --text:#eaecef; --text2:#a7b1bd; --dim:#6b7684;\n    --up:#0ecb81; --down:#f6465d; --accent:#f7c948;\n  }\n  *{box-sizing:border-box;-webkit-tap-highlight-color:transparent;}\n  html,body{margin:0;padding:0;height:100%;}\n  body{\n    background:#07080a;color:var(--text);\n    font-family:\"PingFang SC\",\"HarmonyOS Sans SC\",\"Microsoft YaHei\",system-ui,-apple-system,sans-serif;\n    display:flex;justify-content:center;overflow:hidden;-webkit-font-smoothing:antialiased;\n  }\n  .phone{\n    width:100%;max-width:480px;height:100dvh;background:var(--bg);\n    display:flex;flex-direction:column;position:relative;overflow:hidden;\n    border-left:1px solid #14181c;border-right:1px solid #14181c;\n    padding-top:env(safe-area-inset-top);\n  }\n  @supports not (height:100dvh){ .phone{height:100vh;} }\n\n  /* 顶栏 */\n  .topbar{height:40px;flex:0 0 auto;display:flex;align-items:center;gap:6px;padding:0 14px;}\n  .mark{\n    width:21px;height:21px;border-radius:6px;flex:0 0 auto;position:relative;overflow:hidden;\n    background:linear-gradient(135deg,#fff 0%,#fff 48%,#0b0e11 48%,#0b0e11 56%,#fff 56%,#fff 100%);\n  }\n  .mark:after{content:\"\";position:absolute;inset:0;background:linear-gradient(135deg,transparent 44%,#0b0e11 44%,#0b0e11 56%,transparent 56%);}\n  .brand{font-size:15px;font-weight:600;letter-spacing:.2px;margin-left:4px;}\n  .brand small{color:var(--dim);font-weight:400;font-size:9.5px;margin-left:5px;letter-spacing:.6px;}\n  .topbar .sp{flex:1;}\n  .icon-btn{\n    width:32px;height:32px;border-radius:8px;border:0;background:transparent;\n    color:var(--text2);display:grid;place-items:center;cursor:pointer;transition:background .15s;\n  }\n  .icon-btn:active{background:var(--panel2);}\n  .icon-btn svg{width:17px;height:17px;}\n\n  /* 维度 */\n  .dims{display:flex;gap:6px;padding:0 14px 5px;flex:0 0 auto;}\n  .dim{\n    flex:1;min-width:0;height:28px;border-radius:8px;border:1px solid transparent;\n    background:transparent;color:var(--dim);font-family:inherit;font-size:12.5px;font-weight:500;\n    cursor:pointer;display:flex;align-items:center;justify-content:center;gap:5px;\n    transition:all .16s;white-space:nowrap;\n  }\n  .dim i{width:6px;height:6px;border-radius:50%;opacity:.4;transition:all .16s;flex:0 0 auto;}\n  .dim.on{background:var(--panel2);border-color:#252b32;color:var(--text);font-weight:600;}\n  .dim.on i{opacity:1;box-shadow:0 0 8px currentColor;}\n\n  /* 主数值 */\n  .hero{padding:0 16px 6px;flex:0 0 auto;}\n  .hero-label{font-size:11px;color:var(--dim);letter-spacing:.4px;margin-bottom:2px;display:flex;align-items:center;gap:6px;}\n  .hero-label .dot{width:5px;height:5px;border-radius:50%;background:var(--accent);animation:pulse 2.4s infinite;}\n  @keyframes pulse{0%{box-shadow:0 0 0 0 rgba(255,255,255,.3)}70%{box-shadow:0 0 0 7px rgba(255,255,255,0)}100%{box-shadow:0 0 0 0 rgba(255,255,255,0)}}\n  .hero-value{\n    font-size:31px;line-height:1.1;font-weight:600;letter-spacing:-1px;\n    font-variant-numeric:tabular-nums;display:flex;align-items:baseline;\n  }\n  .hero-value .cur{font-size:19px;font-weight:500;color:var(--text2);margin-right:2px;}\n  .hero-value .dec{font-size:17px;color:var(--text2);letter-spacing:-.5px;}\n  .hero-value .unit{font-size:13px;font-weight:500;color:var(--dim);margin-left:5px;letter-spacing:0;}\n  .hero-meta{display:flex;align-items:center;gap:8px;margin-top:3px;font-size:12px;min-width:0;}\n  .chip{display:inline-flex;align-items:center;gap:3px;padding:2px 7px;border-radius:5px;font-weight:600;\n    font-variant-numeric:tabular-nums;white-space:nowrap;}\n  .chip.up{color:var(--up);background:color-mix(in srgb,var(--up) 12%,transparent);}\n  .chip.down{color:var(--down);background:color-mix(in srgb,var(--down) 12%,transparent);}\n  .chip.flat{color:var(--text2);background:rgba(255,255,255,.05);}\n  .hero-sub{color:var(--dim);font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\n\n  /* 统计 */\n  .stats{display:flex;gap:7px;padding:0 14px 5px;flex:0 0 auto;}\n  .stat{flex:1;background:var(--panel);border:1px solid #191e23;border-radius:9px;padding:5px 8px 6px;min-width:0;}\n  .stat .lab{font-size:9.5px;color:var(--dim);letter-spacing:.2px;margin-bottom:1px;white-space:nowrap;}\n  .stat .val{font-size:14.5px;font-weight:600;font-variant-numeric:tabular-nums;letter-spacing:-.3px;\n    white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\n  .stat .val small{font-size:9px;font-weight:400;color:var(--dim);margin-left:2px;}\n  .stat .bar{height:3px;border-radius:2px;background:#23292f;margin-top:4px;overflow:hidden;}\n  .stat .bar i{display:block;height:100%;border-radius:2px;background:var(--accent);transition:width .4s;}\n\n  /* 周期 */\n  .periods{display:flex;align-items:center;gap:3px;padding:0 12px 2px;flex:0 0 auto;\n    overflow-x:auto;scrollbar-width:none;}\n  .periods::-webkit-scrollbar{display:none;}\n  .periods button{\n    height:21px;padding:0 10px;border-radius:6px;border:0;background:transparent;\n    color:var(--dim);font-size:11.5px;font-weight:500;cursor:pointer;font-family:inherit;\n    transition:all .15s;white-space:nowrap;flex:0 0 auto;\n  }\n  .periods button.on{background:var(--panel2);color:var(--text);font-weight:600;}\n\n  /* 图表 */\n  .chart-wrap{flex:1 1 440px;min-height:340px;position:relative;touch-action:none;cursor:crosshair;}\n  #chart{display:block;width:100%;height:100%;}\n  #chart.fade-in{animation:chartIn .24s ease-out;}\n  @keyframes chartIn{from{opacity:.3}to{opacity:1}}\n  .hud{\n    position:absolute;left:11px;top:5px;pointer-events:none;font-size:9.5px;line-height:1.55;\n    letter-spacing:.1px;font-variant-numeric:tabular-nums;text-shadow:0 1px 3px rgba(0,0,0,.9);\n  }\n  .hud .r{display:flex;gap:6px;white-space:nowrap;}\n  .hud .k{color:#6b7684;}\n  .hud .v{color:#c8d1da;}\n  .hud .v.up{color:var(--up);}\n  .hud .v.down{color:var(--down);}\n  .hud .ma{display:flex;gap:7px;white-space:nowrap;font-size:9px;}\n  .hud .ma b{font-weight:500;}\n\n  /* 实时现价（横盘跳动时高亮） */\n  .hud .live{display:flex;align-items:baseline;gap:6px;margin-bottom:2px;}\n  .hud .live .dot{\n    width:5px;height:5px;border-radius:50%;background:var(--accent);flex:0 0 auto;\n    align-self:center;animation:livePulse 1.6s ease-in-out infinite;\n  }\n  .hud .live .dot.up{background:var(--up);}\n  .hud .live .dot.down{background:var(--down);}\n  @keyframes livePulse{0%,100%{opacity:.3;transform:scale(.8);}50%{opacity:1;transform:scale(1.2);}}\n  .hud .live .num{\n    font:700 16px/1.1 ui-monospace,\"SF Mono\",Menlo,monospace;\n    letter-spacing:-.4px;color:#dfe6ee;\n  }\n  .hud .live .num.up{color:var(--up);}\n  .hud .live .num.down{color:var(--down);}\n  .hud .live .pct{font-size:10px;font-weight:600;color:#8b96a3;}\n  .hud .live .pct.up{color:var(--up);}\n  .hud .live .pct.down{color:var(--down);}\n  @keyframes beatUp{0%{filter:brightness(2.2) drop-shadow(0 0 9px var(--up));}100%{filter:none;}}\n  @keyframes beatDown{0%{filter:brightness(2.2) drop-shadow(0 0 9px var(--down));}100%{filter:none;}}\n  .hud .live .num.beat-up{animation:beatUp .52s ease-out;}\n  .hud .live .num.beat-down{animation:beatDown .52s ease-out;}\n\n  /* 流水 */\n  .ledger{flex:0 0 auto;max-height:9vh;display:flex;flex-direction:column;\n    border-top:1px solid var(--line);background:var(--panel);min-height:0;}\n  .ledger-head{display:flex;align-items:center;justify-content:space-between;\n    padding:7px 16px 4px;font-size:11px;color:var(--dim);flex:0 0 auto;}\n  .ledger-head b{color:var(--text2);font-weight:500;font-size:11.5px;letter-spacing:.3px;}\n  .ledger-list{overflow-y:auto;overscroll-behavior:contain;padding-bottom:4px;}\n  .ledger-list::-webkit-scrollbar{width:0;}\n  .li{display:flex;align-items:center;gap:10px;padding:6px 16px;position:relative;}\n  .li:active{background:rgba(255,255,255,.025);}\n  .li-ico{width:25px;height:25px;border-radius:7px;flex:0 0 auto;display:grid;place-items:center;\n    font-size:12px;font-weight:500;background:rgba(255,255,255,.045);color:var(--text2);}\n  .li-ico.up{color:var(--up);background:color-mix(in srgb,var(--up) 12%,transparent);}\n  .li-ico.down{color:var(--down);background:color-mix(in srgb,var(--down) 12%,transparent);}\n  .li-main{flex:1;min-width:0;}\n  .li-title{font-size:12.5px;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;line-height:1.35;}\n  .li-time{font-size:10px;color:#4e5862;margin-top:1px;font-variant-numeric:tabular-nums;}\n  .li-right{text-align:right;flex:0 0 auto;}\n  .li-amt{font-size:12.5px;font-weight:600;font-variant-numeric:tabular-nums;}\n  .li-amt.up{color:var(--up);}\n  .li-amt.down{color:var(--down);}\n  .li-amt.set{color:var(--text2);}\n  .li-total{font-size:10px;color:#4e5862;margin-top:1px;font-variant-numeric:tabular-nums;}\n  .li-del{position:absolute;right:0;top:0;bottom:0;width:34px;border:0;\n    background:linear-gradient(90deg,transparent,#f6465d);color:#fff;font-size:15px;\n    opacity:0;transition:opacity .18s;cursor:pointer;}\n  .empty{padding:20px 16px;text-align:center;color:#4e5862;font-size:12px;line-height:1.8;}\n\n  /* 底部 */\n  .dock{flex:0 0 auto;display:flex;gap:9px;padding:8px 14px;\n    padding-bottom:calc(8px + env(safe-area-inset-bottom));\n    background:var(--bg);border-top:1px solid var(--line);}\n  .dock button{height:44px;border-radius:10px;border:0;font-family:inherit;font-size:14px;\n    font-weight:600;letter-spacing:.3px;cursor:pointer;transition:transform .1s,opacity .15s;}\n  .dock button:active{transform:scale(.975);}\n  .btn-ghost{flex:0 0 36%;background:var(--panel2);color:var(--text);border:1px solid #262c33 !important;}\n  .btn-primary{flex:1;background:#fff;color:#0b0e11;}\n\n  /* 面板 */\n  .mask{position:fixed;inset:0;background:rgba(0,0,0,.62);opacity:0;pointer-events:none;\n    transition:opacity .22s;z-index:40;backdrop-filter:blur(2px);}\n  .mask.on{opacity:1;pointer-events:auto;}\n  .sheet{\n    position:fixed;left:0;right:0;bottom:0;margin:0 auto;max-width:480px;\n    background:#14181c;border-radius:16px 16px 0 0;z-index:50;\n    transform:translateY(102%);transition:transform .28s cubic-bezier(.32,.72,0,1);\n    padding:8px 18px calc(16px + env(safe-area-inset-bottom));\n    box-shadow:0 -12px 40px rgba(0,0,0,.6);max-height:92dvh;overflow-y:auto;\n  }\n  .sheet.on{transform:translateY(0);}\n  .handle{width:34px;height:4px;border-radius:2px;background:#31383f;margin:4px auto 11px;}\n  .sheet h3{margin:0 0 11px;font-size:15px;font-weight:600;letter-spacing:.3px;}\n\n  .dim-picker{display:flex;gap:6px;margin-bottom:12px;}\n  .dim-picker button{\n    flex:1;height:30px;border-radius:7px;border:1px solid #22282e;background:#0f1215;\n    color:var(--dim);font-family:inherit;font-size:11.5px;cursor:pointer;transition:all .15s;\n  }\n  .dim-picker button.on{background:#262c33;color:#fff;border-color:#333b44;}\n\n  .modes{display:flex;background:#0f1215;border-radius:9px;padding:3px;margin-bottom:12px;}\n  .modes button{flex:1;height:31px;border:0;background:transparent;color:var(--dim);\n    font-family:inherit;font-size:12.5px;font-weight:500;border-radius:7px;cursor:pointer;transition:all .16s;}\n  .modes button.on{background:#262c33;color:#fff;}\n\n  .amount-box{display:flex;align-items:center;gap:6px;border-bottom:1px solid #262c33;padding:4px 2px 8px;margin-bottom:11px;}\n  .amount-box .cur{font-size:25px;color:var(--text2);}\n  .amount-box input{\n    flex:1;min-width:0;background:transparent;border:0;outline:0;color:#fff;\n    font-size:28px;font-weight:600;font-family:inherit;letter-spacing:-.5px;\n    font-variant-numeric:tabular-nums;\n  }\n  .amount-box input::placeholder{color:#2f373f;}\n  .quick{display:flex;gap:6px;margin-bottom:11px;}\n  .quick button{\n    flex:1;min-width:0;height:31px;border-radius:7px;border:1px solid #232a31;background:#0f1215;\n    color:var(--text2);font-family:inherit;font-size:12px;cursor:pointer;font-variant-numeric:tabular-nums;\n  }\n  .quick button:active{background:#1a1f24;}\n\n  .moods{display:flex;gap:7px;margin:2px 0 14px;}\n  .mood{\n    flex:1;height:68px;border-radius:11px;border:1px solid #232a31;background:#0f1215;\n    display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;\n    cursor:pointer;transition:all .16s;font-family:inherit;color:#5c6672;\n  }\n  .mood svg{width:25px;height:25px;stroke:currentColor;transition:all .16s;}\n  .mood span{font-size:9.5px;color:#4e5862;transition:all .16s;}\n  .mood.sel span{color:var(--text);}\n\n  .note-input{\n    width:100%;height:40px;border-radius:8px;border:1px solid #232a31;background:#0f1215;\n    color:#fff;padding:0 12px;font-family:inherit;font-size:13px;outline:0;margin-bottom:13px;\n  }\n  .note-input::placeholder{color:#3c454e;}\n  .confirm{\n    width:100%;height:46px;border-radius:10px;border:0;background:#fff;color:#0b0e11;\n    font-family:inherit;font-size:15px;font-weight:600;cursor:pointer;letter-spacing:.4px;\n  }\n  .confirm:active{opacity:.85;}\n  .sheet-tip{text-align:center;font-size:11px;color:#4e5862;margin-top:10px;font-variant-numeric:tabular-nums;}\n\n  /* 设置/统计 */\n  .set-row{display:flex;align-items:center;justify-content:space-between;padding:11px 0;\n    border-bottom:1px solid #1d2227;font-size:13.5px;gap:12px;}\n  .set-row:last-of-type{border-bottom:0;}\n  .set-row .desc{font-size:10.5px;color:#4e5862;margin-top:2px;line-height:1.4;}\n  .seg2{display:flex;background:#0f1215;border-radius:7px;padding:3px;flex:0 0 auto;}\n  .seg2 button{border:0;background:transparent;color:var(--dim);font-family:inherit;\n    font-size:11.5px;padding:5px 10px;border-radius:5px;cursor:pointer;}\n  .seg2 button.on{background:#262c33;color:#fff;}\n  .tgt-input{\n    width:92px;height:30px;border-radius:7px;border:1px solid #232a31;background:#0f1215;\n    color:#fff;text-align:right;padding:0 8px;font-family:inherit;font-size:12.5px;\n    font-variant-numeric:tabular-nums;outline:0;\n  }\n  .danger{width:100%;height:40px;border-radius:9px;border:1px solid #3a2026;\n    background:rgba(246,70,93,.06);color:var(--down);font-family:inherit;font-size:13px;\n    margin-top:9px;cursor:pointer;}\n  .minor{width:100%;height:40px;border-radius:9px;border:1px solid #262c33;background:#0f1215;\n    color:var(--text2);font-family:inherit;font-size:13px;margin-top:9px;cursor:pointer;}\n\n  .ov-row{display:flex;align-items:center;gap:9px;padding:8px 0;border-bottom:1px solid #191e23;font-size:13px;}\n  .ov-row i{width:7px;height:7px;border-radius:50%;flex:0 0 auto;}\n  .ov-row .n{flex:1;color:var(--text2);}\n  .ov-row .v{font-variant-numeric:tabular-nums;font-weight:600;}\n  .ov-row .c{font-size:10.5px;color:#4e5862;margin-left:4px;font-weight:400;font-variant-numeric:tabular-nums;}\n\n  .heat{display:flex;gap:3px;margin:10px 0 5px;}\n  .heat-col{flex:1;display:flex;flex-direction:column;gap:3px;}\n  .heat-cell{width:100%;height:13px;border-radius:2px;background:#1a1f25;}\n  .heat-legend{display:flex;align-items:center;gap:4px;justify-content:flex-end;\n    font-size:9px;color:#4e5862;margin-bottom:10px;}\n  .heat-legend i{width:8px;height:8px;border-radius:2px;display:block;}\n\n  .badges{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin:4px 0 10px;}\n  .badge{border:1px solid #1d2227;border-radius:9px;padding:8px 3px 7px;text-align:center;\n    background:#0f1215;opacity:.32;transition:all .2s;}\n  .badge.on{opacity:1;border-color:#2c333b;background:#161b20;}\n  .badge .ic{font-size:16px;line-height:1;margin-bottom:3px;filter:grayscale(1);}\n  .badge.on .ic{filter:none;}\n  .badge .nm{font-size:8.5px;color:var(--text2);line-height:1.3;white-space:nowrap;}\n\n  .sec-title{font-size:11px;color:var(--dim);letter-spacing:.4px;margin:14px 0 2px;}\n  .toast{\n    position:fixed;left:50%;top:50%;transform:translate(-50%,-50%) scale(.94);\n    background:rgba(30,35,41,.96);color:#fff;font-size:13px;padding:10px 18px;border-radius:9px;\n    z-index:99;opacity:0;pointer-events:none;transition:all .2s;white-space:nowrap;\n    box-shadow:0 8px 30px rgba(0,0,0,.5);\n  }\n  .toast.on{opacity:1;transform:translate(-50%,-50%) scale(1);}\n<\/style>\n<\/head>\n<body>\n\n<div class=\"phone\">\n  <header class=\"topbar\">\n    <div class=\"mark\"><\/div>\n    <div class=\"brand\">人生账本<small>LIFE LEDGER<\/small><small id=\"brandVer\" style=\"color:#4a5560;font-size:9px;letter-spacing:.5px;margin-left:2px\"><\/small><\/div>\n    <div class=\"sp\"><\/div>\n    <button class=\"icon-btn\" id=\"btnStats\" aria-label=\"数据\">\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\">\n        <path d=\"M4 20V10M10 20V4M16 20v-7M22 20H2\"/>\n      <\/svg>\n    <\/button>\n    <button class=\"icon-btn\" id=\"btnSettings\" aria-label=\"设置\">\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\">\n        <circle cx=\"12\" cy=\"12\" r=\"3.2\"/>\n        <path d=\"M19.4 15a1.7 1.7 0 0 0 .34 1.87l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.7 1.7 0 0 0-1.87-.34 1.7 1.7 0 0 0-1.03 1.56V21a2 2 0 1 1-4 0v-.11a1.7 1.7 0 0 0-1.11-1.56 1.7 1.7 0 0 0-1.87.34l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06a1.7 1.7 0 0 0 .34-1.87 1.7 1.7 0 0 0-1.56-1.03H3a2 2 0 1 1 0-4h.11A1.7 1.7 0 0 0 4.67 8.9a1.7 1.7 0 0 0-.34-1.87l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06a1.7 1.7 0 0 0 1.87.34H9a1.7 1.7 0 0 0 1-1.56V3a2 2 0 1 1 4 0v.11a1.7 1.7 0 0 0 1.03 1.56 1.7 1.7 0 0 0 1.87-.34l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06a1.7 1.7 0 0 0-.34 1.87V9a1.7 1.7 0 0 0 1.56 1H21a2 2 0 1 1 0 4h-.11a1.7 1.7 0 0 0-1.49 1z\"/>\n      <\/svg>\n    <\/button>\n  <\/header>\n\n  <div class=\"dims\" id=\"dims\"><\/div>\n\n  <section class=\"hero\">\n    <div class=\"hero-label\"><span class=\"dot\"><\/span><span id=\"heroLabel\">总身价 · CNY<\/span><\/div>\n    <div class=\"hero-value\" id=\"heroValue\"><span class=\"cur\">¥<\/span>--<\/div>\n    <div class=\"hero-meta\">\n      <span class=\"chip flat\" id=\"heroChange\">--<\/span>\n      <span class=\"hero-sub\" id=\"heroSub\">暂无记录<\/span>\n    <\/div>\n  <\/section>\n\n  <div class=\"stats\">\n    <div class=\"stat\">\n      <div class=\"lab\">目标进度<\/div>\n      <div class=\"val\" id=\"stGoal\">--<\/div>\n      <div class=\"bar\"><i id=\"stBar\" style=\"width:0%\"><\/i><\/div>\n    <\/div>\n    <div class=\"stat\">\n      <div class=\"lab\" id=\"stChgLab\">7 日变化<\/div>\n      <div class=\"val\" id=\"stChg\">--<\/div>\n      <div class=\"bar\"><i id=\"stChgBar\" style=\"width:0%\"><\/i><\/div>\n    <\/div>\n    <div class=\"stat\">\n      <div class=\"lab\">连续记录<\/div>\n      <div class=\"val\" id=\"stStreak\">0<small>天<\/small><\/div>\n      <div class=\"bar\"><i id=\"stStreakBar\" style=\"width:0%;background:#5b8def\"><\/i><\/div>\n    <\/div>\n  <\/div>\n\n  <div class=\"periods\" id=\"periods\"><\/div>\n\n  <div class=\"chart-wrap\" id=\"chartWrap\">\n    <canvas id=\"chart\"><\/canvas>\n    <div class=\"hud\" id=\"hud\"><\/div>\n  <\/div>\n\n  <section class=\"ledger\">\n    <div class=\"ledger-head\"><b id=\"ledgerTitle\">流水明细<\/b><span id=\"ledgerCount\"><\/span><\/div>\n    <div class=\"ledger-list\" id=\"ledgerList\"><\/div>\n  <\/section>\n\n  <div class=\"dock\">\n    <button class=\"btn-ghost\" id=\"btnSub\">− 减少<\/button>\n    <button class=\"btn-primary\" id=\"btnAdd\">＋ 增加<\/button>\n  <\/div>\n<\/div>\n\n<div class=\"mask\" id=\"mask\"><\/div>\n\n<div class=\"sheet\" id=\"sheetEdit\">\n  <div class=\"handle\"><\/div>\n  <h3 id=\"sheetTitle\">记一笔<\/h3>\n  <div class=\"dim-picker\" id=\"dimPicker\"><\/div>\n  <div class=\"modes\" id=\"modes\">\n    <button data-m=\"add\" class=\"on\">增加<\/button>\n    <button data-m=\"sub\">减少<\/button>\n    <button data-m=\"set\">设定<\/button>\n  <\/div>\n  <div id=\"panelNum\">\n    <div class=\"amount-box\">\n      <span class=\"cur\" id=\"amountCur\">¥<\/span>\n      <input id=\"amount\" type=\"text\" inputmode=\"decimal\" placeholder=\"0\" autocomplete=\"off\" />\n    <\/div>\n    <div class=\"quick\" id=\"quick\"><\/div>\n  <\/div>\n  <div id=\"panelMood\" style=\"display:none\">\n    <div class=\"moods\" id=\"moods\"><\/div>\n  <\/div>\n  <input id=\"note\" class=\"note-input\" type=\"text\" placeholder=\"备注（可选）\" maxlength=\"18\" />\n  <button class=\"confirm\" id=\"confirmBtn\">确认<\/button>\n  <div class=\"sheet-tip\" id=\"sheetTip\"><\/div>\n<\/div>\n\n<div class=\"sheet\" id=\"sheetStats\">\n  <div class=\"handle\"><\/div>\n  <h3>数据概览<\/h3>\n  <div id=\"overview\"><\/div>\n  <div class=\"sec-title\">近 13 周记录密度<\/div>\n  <div class=\"heat\" id=\"heat\"><\/div>\n  <div class=\"heat-legend\">\n    <span>少<\/span><i style=\"background:#1a1f25\"><\/i><i style=\"background:rgba(14,203,129,.28)\"><\/i>\n    <i style=\"background:rgba(14,203,129,.55)\"><\/i><i style=\"background:rgba(14,203,129,.85)\"><\/i><span>多<\/span>\n  <\/div>\n  <div class=\"sec-title\">成就<\/div>\n  <div class=\"badges\" id=\"badges\"><\/div>\n<\/div>\n\n<div class=\"sheet\" id=\"sheetSet\">\n  <div class=\"handle\"><\/div>\n  <h3>设置<\/h3>\n  <div class=\"set-row\">\n    <div><div>涨跌配色<\/div><div class=\"desc\">欧易为绿涨红跌<\/div><\/div>\n    <div class=\"seg2\" id=\"colorMode\">\n      <button data-c=\"okx\" class=\"on\">绿涨红跌<\/button>\n      <button data-c=\"cn\">红涨绿跌<\/button>\n    <\/div>\n  <\/div>\n  <div class=\"set-row\">\n    <div><div>身价目标<\/div><div class=\"desc\">K 线上会画出目标虚线<\/div><\/div>\n    <input class=\"tgt-input\" id=\"tgtWealth\" type=\"text\" inputmode=\"numeric\" />\n  <\/div>\n  <div class=\"set-row\">\n    <div><div>成长目标<\/div><div class=\"desc\">累计点数<\/div><\/div>\n    <input class=\"tgt-input\" id=\"tgtGrowth\" type=\"text\" inputmode=\"numeric\" />\n  <\/div>\n  <div class=\"set-row\">\n    <div><div>心情 / 健康目标<\/div><div class=\"desc\">满分制下的目标分<\/div><\/div>\n    <input class=\"tgt-input\" id=\"tgtScore\" type=\"text\" inputmode=\"numeric\" />\n  <\/div>\n  <div class=\"set-row\" style=\"display:block;\">\n    <div><div>板块清零<\/div><div class=\"desc\" style=\"margin-bottom:8px;\">单独清空某个板块的记录（清「持仓」会连持仓商品一起清掉），其他板块不受影响<\/div><\/div>\n    <div style=\"display:flex;gap:6px;flex-wrap:wrap;\" id=\"dimClear\"><\/div>\n  <\/div>\n  <div class=\"set-row\">\n    <div><div>一键重置<\/div><div class=\"desc\">清空全部数据，重新设定起点<\/div><\/div>\n    <button class=\"icon-btn\" id=\"btnResetAll\" style=\"color:var(--down);font-size:12px;width:auto;padding:0 10px;height:30px;background:#0f1215;border-radius:7px;border:1px solid #3a2026;\">重置<\/button>\n  <\/div>\n  <div class=\"set-row\">\n    <div><div>行情自动更新<\/div><div class=\"desc\">每 15 分钟同步一次持仓价格<\/div><\/div>\n    <div class=\"seg2\" id=\"syncMode\">\n      <button data-s=\"15\" class=\"on\">15 分钟<\/button>\n      <button data-s=\"60\">1 小时<\/button>\n    <\/div>\n  <\/div>\n  <div class=\"set-row\" style=\"display:block;\">\n    <div><div>软件更新<\/div><div class=\"desc\" style=\"margin-bottom:6px;\">已内置官方更新源，直接点「检查更新」即可；新版本会自动下载，重启应用生效，无需重装 APK。也可填写自己的更新源地址覆盖。<\/div><\/div>\n    <input class=\"note-input\" id=\"updUrl\" type=\"text\" placeholder=\"留空 = 使用官方更新源\" style=\"width:100%;\" />\n    <div style=\"display:flex;gap:8px;align-items:center;margin-top:8px;\">\n      <button class=\"icon-btn\" id=\"btnCheckUpd\" style=\"font-size:12px;width:auto;padding:0 12px;height:30px;background:#0f1215;border-radius:7px;border:1px solid #232a31;color:var(--text2);\">检查更新<\/button>\n      <span id=\"updStatus\" style=\"font-size:10.5px;color:var(--dim);\"><\/span>\n    <\/div>\n  <\/div>\n  <button class=\"minor\" id=\"btnExport\">导出数据备份（JSON）<\/button>\n  <button class=\"minor\" id=\"btnImport\">导入数据备份<\/button>\n  <button class=\"minor\" id=\"btnRestore\">从自动备份恢复<\/button>\n  <div style=\"margin-top:10px;padding:10px 12px;background:#0f1215;border:1px solid #232a31;border-radius:9px;\">\n    <div style=\"font-size:10.5px;color:var(--dim);margin-bottom:6px;\">异常排查 · 诊断信息<\/div>\n    <pre id=\"diagText\" style=\"font:10px ui-monospace,monospace;color:#8fa0b0;white-space:pre-wrap;word-break:break-all;margin:0 0 8px;line-height:1.6;\">--<\/pre>\n    <button class=\"icon-btn\" id=\"btnDiag\" style=\"font-size:12px;width:auto;padding:0 12px;height:30px;background:#151b21;border-radius:7px;border:1px solid #232a31;color:var(--text2);\">刷新并复制诊断<\/button>\n  <\/div>\n  <div class=\"sheet-tip\" style=\"padding:0 16px 6px;\">每次改动会自动留 3 份快照（至少间隔 5 分钟），误删或误清零可用它找回。建议定期导出 JSON 存到别处。<\/div>\n  <input type=\"file\" id=\"fileImport\" accept=\".json,application/json\" style=\"display:none\" />\n  <button class=\"danger\" id=\"btnClearDemo\">清空演示数据，开始记我自己的<\/button>\n  <button class=\"danger\" id=\"btnClearAll\">清空全部记录<\/button>\n  <div style=\"text-align:center;font-size:10px;color:#3c454e;margin-top:13px;line-height:1.7;\">\n    数据仅保存在这台设备 · 卸载应用即全部清除 · v<span id=\"verText\"><\/span>\n  <\/div>\n<\/div>\n\n<div class=\"sheet\" id=\"sheetAsset\">\n  <div class=\"handle\"><\/div>\n  <h3>添加商品<\/h3>\n  <div class=\"modes\" id=\"assetKind\">\n    <button data-k=\"crypto\" class=\"on\">加密币<\/button>\n    <button data-k=\"stock\">股票<\/button>\n    <button data-k=\"gold\">黄金(克)<\/button>\n    <button data-k=\"goods\">日常用品<\/button>\n  <\/div>\n  <div class=\"quick\" id=\"assetQuick\"><\/div>\n  <input id=\"assetName\" class=\"note-input\" type=\"text\" placeholder=\"名称（如：比特币）\" maxlength=\"12\" />\n  <input id=\"assetCode\" class=\"note-input\" type=\"text\" placeholder=\"代码（如 bitcoin）\" maxlength=\"20\" />\n  <input id=\"assetPrice\" class=\"note-input\" type=\"text\" inputmode=\"decimal\" placeholder=\"单价（元）\" style=\"display:none\" />\n  <input id=\"assetUnit\" class=\"note-input\" type=\"text\" placeholder=\"单位（袋 / 瓶 / 台，可选）\" maxlength=\"4\" style=\"display:none\" />\n  <input id=\"assetQty\" class=\"note-input\" type=\"text\" inputmode=\"decimal\" placeholder=\"持有数量（黄金单位：克）\" />\n  <button class=\"confirm\" id=\"assetConfirm\">添加并获取实时行情<\/button>\n  <div class=\"sheet-tip\">加密币/黄金走 gate.io，股票走腾讯行情，汇率自动更新 · 每 15 分钟同步一次<\/div>\n<\/div>\n\n<div class=\"toast\" id=\"toast\"><\/div>\n\n<script>\n/* ============ 应用内热更新加载器（必须在主脚本之前） ============\n   核心机制：【文档代际守卫】\n   热更新用 document.write 整体替换页面时，旧文档的主脚本已经跑完，\n   它的 setInterval / setTimeout / requestAnimationFrame 回调全部还活着，\n   而且回调里的 $() 会查到【新文档】的元素继续写旧数据——\n   这就是\"顶部数字在两个值之间来回跳、怎么修新版都没用\"的根源。\n   解法：给每个文档发一个代数号。定时器回调创建时记下自己文档的代数，\n   回调触发时发现代数变了（页面已被新文档替换）就立刻自毁。\n   write 前再递增一次代数 → 旧文档的定时器全体阵亡。\n   sessionStorage 防止同一会话内反复替换造成死循环。 */\n(function(){\n  var GEN = \"__LEDGER_GEN__\";\n  window[GEN] = (window[GEN] || 0) + 1;\n\n  /* 幂等守卫包装：代数在【注册时】捕获（而非包装器闭包的代数）。\n     ⚠️ 不能用闭包代数比较——write 后新文档的 loader 会再包一层，\n     壳那层的代数早已过期，会把新文档自己的定时器也全部误杀。 */\n  function wrapTimer(orig){\n    if(orig.__ledgerGuarded) return orig;      /* 已守卫过，幂等返回 */\n    var wrapped = function(fn){\n      var a = arguments;\n      if(typeof fn === \"function\" && !fn.__ledgerGen){\n        var g = window[GEN];                   /* 注册时的当前代数 */\n        var w = function(){\n          if(window[GEN] !== g) return;        /* 已换代：过期回调自毁 */\n          return fn.apply(this, arguments);\n        };\n        w.__ledgerGen = g;\n        return orig(w, a[1]);\n      }\n      return orig.apply(this, arguments);\n    };\n    wrapped.__ledgerGuarded = true;\n    return wrapped;\n  }\n  window.setInterval = wrapTimer(window.setInterval);\n  window.setTimeout = wrapTimer(window.setTimeout);\n  /* rAF 不包装：壳文档的 rAF 只画离屏画布，无害；\n     会写 DOM 的路径（hero 写入）由 MutationObserver 防线兜底 */\n\n  function applyUpdate(){\n    try{\n      var h = localStorage.getItem(\"upd_html\");\n      var v = localStorage.getItem(\"upd_ver\");\n      if(h && v && h.length > 5000 && h.indexOf(\"<!DOCTYPE\") === 0 &&\n         sessionStorage.getItem(\"upd_applied\") !== v){\n        sessionStorage.setItem(\"upd_applied\", v);\n        window[GEN] = (window[GEN] || 0) + 1;   /* 本文档（壳）的定时器全体阵亡 */\n        try{ window.stop(); }catch(e){}\n        document.open();\n        document.write(h);\n        document.close();\n      }\n    }catch(e){ try{ console.error(\"UPD-APPLY-FAIL: \" + (e && e.message)); }catch(e2){} }\n  }\n  if(document.readyState === \"loading\"){\n    document.addEventListener(\"DOMContentLoaded\", applyUpdate);\n  } else {\n    applyUpdate();\n  }\n})();\n<\/script>\n<script>\n(function(){\n\"use strict\";\n\n/* ============ 工具 ============ */\nconst $ = s => document.querySelector(s);\nconst pad2 = n => String(n).padStart(2, \"0\");\nconst clamp = (v, a, b) => Math.min(b, Math.max(a, v));\n\n/* 应用版本号：每次发布更新时递增（与 Android versionName 保持一致） */\nconst APP_VERSION = \"5.18\";\n\n/* 官方更新源：按顺序尝试，任一可达即可（均带跨域许可）。\n   注意：托管地址带 sharecode，URL 需保留 query 参数。 */\nconst UPDATE_SOURCES = [\n  \"https://life-ledger-updates.app.workbuddy.host?sharecode=Z3PH4HVA3C\"\n];\n\n/* 拼出更新源上的某个文件地址（保留 base 上已有的 query 参数） */\nfunction srcUrl(base, file){\n  const qi = base.indexOf(\"?\");\n  const path = qi < 0 ? base : base.slice(0, qi);\n  const qs = qi < 0 ? \"\" : base.slice(qi + 1);\n  return path.replace(/\\/+$/, \"\") + \"/\" + file + \"?\" + (qs ? qs + \"&\" : \"\") + \"t=\" + Date.now();\n}\n\n/* 版本号比较：5.2 > 5.1.3 之类 */\nfunction cmpVer(a, b){\n  const pa = String(a).split(\".\").map(Number), pb = String(b).split(\".\").map(Number);\n  for(let i = 0; i < Math.max(pa.length, pb.length); i++){\n    const x = pa[i] || 0, y = pb[i] || 0;\n    if(x !== y) return x - y;\n  }\n  return 0;\n}\n\n/* 应用内检查更新：用 <script> 加载更新包（script 不受跨域限制，\n   托管平台即使不给 CORS 头也能取到）。更新包形如：\n   window.__LEDGER_UPD__ = { version: \"5.3\", html: \"<!DOCTYPE html>...\" }\n   拿到新版本 HTML 存本地，下次启动自动应用。多个源按顺序尝试。 */\nfunction loadUpdateJs(base){\n  return new Promise((resolve, reject) => {\n    const s = document.createElement(\"script\");\n    let done = false;\n    const finish = (ok, val) => {\n      if(done) return;\n      done = true;\n      s.remove();\n      if(ok){ resolve(val); } else { reject(val); }\n    };\n    s.charset = \"utf-8\";\n    s.src = srcUrl(base, \"update.js\");\n    s.onload = () => {\n      const u = window.__LEDGER_UPD__;\n      try { delete window.__LEDGER_UPD__; } catch(e){ window.__LEDGER_UPD__ = undefined; }\n      if(u && u.version && typeof u.html === \"string\" && u.html.length > 5000) finish(true, u);\n      else finish(false, new Error(\"更新数据无效\"));\n    };\n    s.onerror = () => finish(false, new Error(\"加载失败\"));\n    setTimeout(() => finish(false, new Error(\"超时\")), 20000);\n    document.head.appendChild(s);\n  });\n}\n\nasync function checkUpdate(manual){\n  const st = $(\"#updStatus\");\n  const custom = (S.updateUrl || \"\").trim().replace(/\\/+$/, \"\");\n  const urls = custom ? [custom].concat(UPDATE_SOURCES) : UPDATE_SOURCES.slice();\n  if(manual && st) st.textContent = \"正在检查更新…\";\n  let lastErr = \"\";\n  for(const url of urls){\n    try{\n      const u = await loadUpdateJs(url);\n      const c = cmpVer(String(u.version), APP_VERSION);\n      if(c > 0){\n        localStorage.setItem(\"upd_html\", u.html);\n        localStorage.setItem(\"upd_ver\", String(u.version));\n        if(st) st.textContent = \"发现新版本 v\" + u.version + \" · 重启应用后生效\";\n        toast(\"已下载 v\" + u.version + \"，重启应用生效\");\n      } else if(c < 0){\n        /* 远程版本比当前还旧（回滚），清除本地更新 */\n        localStorage.removeItem(\"upd_html\");\n        localStorage.removeItem(\"upd_ver\");\n        if(st) st.textContent = \"当前 v\" + APP_VERSION;\n      } else {\n        /* 远程与当前同版本：清掉本地残留的更新包，\n           否则每次启动 loader 都会把整个页面重写一遍 */\n        localStorage.removeItem(\"upd_html\");\n        localStorage.removeItem(\"upd_ver\");\n        if(st) st.textContent = \"已是最新版本 v\" + APP_VERSION;\n        if(manual) toast(\"已是最新版本 v\" + APP_VERSION);\n      }\n      return;                   /* 任一源成功即结束 */\n    }catch(e){\n      lastErr = e.message;\n    }\n  }\n  if(st) st.textContent = \"检查失败：\" + (lastErr || \"网络不可用\");\n  if(manual) toast(\"检查更新失败：\" + (lastErr || \"网络不可用\"));\n}\nconst KEY = \"life_ledger_v2\";\nconst BK_KEY = \"life_ledger_backup\";      /* 自动滚动备份（最多 3 份） */\nconst OLD_KEY = \"networth_kline_v1\";\n\nfunction fmtMoney(n, dec){\n  const d = (dec === undefined) ? 2 : dec;\n  return n.toLocaleString(\"zh-CN\", { minimumFractionDigits: d, maximumFractionDigits: d });\n}\nfunction fmtShort(n){\n  const a = Math.abs(n);\n  if(a >= 1e8) return (n/1e8).toFixed(2) + \"亿\";\n  if(a >= 1e4) return (n/1e4).toFixed(a >= 1e6 ? 0 : 1) + \"万\";\n  return n.toFixed(0);\n}\nfunction dstr(ts){ const d = new Date(ts); return pad2(d.getMonth()+1) + \"/\" + pad2(d.getDate()); }\nfunction dtimeShort(ts){\n  const d = new Date(ts);\n  return pad2(d.getMonth()+1) + \"-\" + pad2(d.getDate()) + \" \" + pad2(d.getHours()) + \":\" + pad2(d.getMinutes());\n}\nfunction dayKey(ts){\n  const d = new Date(ts);\n  return d.getFullYear() + \"-\" + pad2(d.getMonth()+1) + \"-\" + pad2(d.getDate());\n}\nlet toastTimer = 0;\nfunction toast(msg){\n  const el = $(\"#toast\");\n  el.textContent = msg;\n  el.classList.add(\"on\");\n  clearTimeout(toastTimer);\n  toastTimer = setTimeout(() => el.classList.remove(\"on\"), 1700);\n}\nfunction escapeHtml(s){\n  return String(s).replace(/[&<>\"']/g, m => ({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[m]));\n}\n\n/* ============ 维度 ============ */\nconst DIMS = [\n  { key:\"wealth\", name:\"身价\", kind:\"money\",  color:\"#f7c948\", label:\"总身价 · CNY\",   target:1000000, quick:[1000,5000,10000,50000,100000] },\n  { key:\"growth\", name:\"成长\", kind:\"points\", color:\"#5b8def\", label:\"成长值 · 累计\",   target:6000,    quick:[10,30,50,100,200] },\n  { key:\"mood\",   name:\"心情\", kind:\"score\",  color:\"#ff7ab6\", label:\"心情指数 · 今日\", target:9,       quick:[] },\n  { key:\"health\", name:\"健康\", kind:\"score\",  color:\"#3ecf8e\", label:\"健康指数 · 今日\", target:9,       quick:[] },\n  { key:\"assets\", name:\"持仓\", kind:\"money\",  color:\"#c77dff\", label:\"持仓市值 · CNY\", target:0,       quick:[] }\n];\nconst DMAP = {};\nDIMS.forEach(d => { DMAP[d.key] = d; });\n\nconst MOODS = [\n  { v:2,  t:\"很糟\", face:\"sad\" },\n  { v:4,  t:\"低落\", face:\"low\" },\n  { v:6,  t:\"一般\", face:\"mid\" },\n  { v:8,  t:\"不错\", face:\"good\" },\n  { v:10, t:\"很棒\", face:\"great\" }\n];\nconst MOOD_COLORS = [\"#f6465d\", \"#f7931a\", \"#a7b1bd\", \"#3ecf8e\", \"#0ecb81\"];\n\nfunction faceSVG(type){\n  const eyes = '<circle cx=\"9\" cy=\"10\" r=\"1.1\" fill=\"currentColor\" stroke=\"none\"/>' +\n               '<circle cx=\"15\" cy=\"10\" r=\"1.1\" fill=\"currentColor\" stroke=\"none\"/>';\n  let mouth = \"\";\n  if(type === \"sad\")   mouth = '<path d=\"M8.6 16.4c1-1.5 2-2.2 3.4-2.2s2.4.7 3.4 2.2\"/>';\n  if(type === \"low\")   mouth = '<path d=\"M8.8 15.8c1-1 2-1.5 3.2-1.5s2.2.5 3.2 1.5\"/>';\n  if(type === \"mid\")   mouth = '<path d=\"M8.6 15.2h6.8\"/>';\n  if(type === \"good\")  mouth = '<path d=\"M8.8 14.4c1 1.2 2 1.8 3.2 1.8s2.2-.6 3.2-1.8\"/>';\n  if(type === \"great\") mouth = '<path d=\"M8.4 13.8c1.2 1.8 2.4 2.6 3.6 2.6s2.4-.8 3.6-2.6\"/>';\n  return '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\">' +\n         '<circle cx=\"12\" cy=\"12\" r=\"9\"/>' + eyes + mouth + '<\/svg>';\n}\n\n/* ============ 状态 ============ */\nlet S = {\n  entries: [],\n  assets: [],\n  lastSync: 0,\n  usdCny: 7.2,\n  hkdCny: 0.92,\n  fxT: 0,\n  syncMin: 15,\n  colorMode: \"okx\",\n  updateUrl: \"\",\n  targets: { wealth:1000000, growth:6000, mood:9, health:9, assets:0 },\n  seeded: false,\n  achievements: []\n};\n/* 周期：ms>0 的用固定时间桶聚合 */\nconst PERIODS = [\n  { g:\"sec\",  name:\"秒\",   ms:1000,    count:60, back:60,  chg:\"近 60 秒变化\" },\n  { g:\"1m\",   name:\"1分\",  ms:60e3,    count:60, back:60,  chg:\"近 60 分变化\" },\n  { g:\"15m\",  name:\"15分\", ms:900e3,   count:48, back:48,  chg:\"近 12 时变化\" },\n  { g:\"30m\",  name:\"30分\", ms:1800e3,  count:40, back:48,  chg:\"近 24 时变化\" },\n  { g:\"1h\",   name:\"1时\",  ms:3600e3,  count:40, back:24,  chg:\"近 24 时变化\" },\n  { g:\"4h\",   name:\"4时\",  ms:14400e3, count:36, back:21,  chg:\"近 3 天变化\" },\n  { g:\"8h\",   name:\"8时\",  ms:28800e3, count:32, back:21,  chg:\"近一周变化\" },\n  { g:\"day\",  name:\"日\",   ms:0, count:46, back:7,  chg:\"7 日变化\" },\n  { g:\"week\", name:\"周\",   ms:0, count:40, back:4,  chg:\"4 周变化\" },\n  { g:\"month\",name:\"月\",   ms:0, count:24, back:3,  chg:\"3 月变化\" }\n];\nconst PMAP = {};\nPERIODS.forEach(p => { PMAP[p.g] = p; });\n\nlet curDim = \"wealth\";\nlet gran = \"day\";\n\nfunction save(){\n  try {\n    const json = JSON.stringify(S);\n    const prev = localStorage.getItem(KEY);\n    /* 自动滚动备份：数据有变化、且距上次备份超过 5 分钟时留一份旧快照。\n       这样误删/误清零之后还能找回。 */\n    if(prev && prev !== json){\n      try {\n        let baks = [];\n        try { baks = JSON.parse(localStorage.getItem(BK_KEY) || \"[]\"); } catch(e){ baks = []; }\n        if(!Array.isArray(baks)) baks = [];\n        const last = baks[0];\n        if(!last || Date.now() - last.t > 5 * 60e3){\n          baks.unshift({ t: Date.now(), json: prev });\n          baks = baks.slice(0, 3);\n          localStorage.setItem(BK_KEY, JSON.stringify(baks));\n        }\n      } catch(e){}\n    }\n    localStorage.setItem(KEY, json);\n  } catch(e){}\n}\n\n/* 从自动备份恢复 */\nfunction restoreFromBackup(){\n  let baks = [];\n  try { baks = JSON.parse(localStorage.getItem(BK_KEY) || \"[]\"); } catch(e){ baks = []; }\n  if(!Array.isArray(baks) || !baks.length){ toast(\"暂无自动备份\"); return; }\n  const lines = baks.map((b, i) => {\n    let n = 0;\n    try { n = (JSON.parse(b.json).entries || []).length; } catch(e){ n = 0; }\n    return \"  \" + (i + 1) + \". \" + dtimeShort(b.t) + \" — \" + n + \" 条记录\";\n  });\n  const pick = prompt(\"选择要恢复的备份（输入序号）：\\n\" + lines.join(\"\\n\"));\n  if(pick === null) return;\n  const i = parseInt(String(pick).replace(/[^\\d]/g, \"\"), 10) - 1;\n  if(!(i >= 0 && i < baks.length)){ toast(\"序号无效\"); return; }\n  if(!confirm(\"将用「\" + dtimeShort(baks[i].t) + \"」的备份覆盖当前数据，确定吗？\")) return;\n  try {\n    localStorage.setItem(KEY, baks[i].json);\n    load();\n    rebuild();\n    renderAll();\n    toast(\"已恢复 \" + dtimeShort(baks[i].t) + \" 的备份\");\n  } catch(e){\n    toast(\"恢复失败：\" + e.message);\n  }\n}\n\nfunction load(){\n  let raw = null;\n  try { raw = localStorage.getItem(KEY); } catch(e){}\n  if(raw){\n    let ok = false;\n    try {\n      const o = JSON.parse(raw);\n      if(o && Array.isArray(o.entries)){\n        S.entries = o.entries.map(e => ({\n          id: e.id, t: e.t, mode: e.mode, amount: e.amount,\n          note: e.note || \"\", dim: e.dim || \"wealth\"\n        }));\n        S.assets = Array.isArray(o.assets) ? o.assets : [];\n        S.lastSync = o.lastSync || 0;\n        S.usdCny = o.usdCny || 7.2;\n        S.hkdCny = o.hkdCny || 0.92;\n        S.fxT = o.fxT || 0;\n        S.syncMin = o.syncMin || 15;\n        S.colorMode = o.colorMode || \"okx\";\n        S.updateUrl = o.updateUrl || \"\";\n        S.targets = Object.assign(S.targets, o.targets || {});\n        S.achievements = o.achievements || [];\n        S.seeded = true;\n        ok = true;\n      }\n    } catch(e){}\n    if(!ok){\n      /* 有数据但读不出来：另存原始副本，绝不用演示数据覆盖用户记录 */\n      try { localStorage.setItem(\"life_ledger_raw_\" + Date.now(), raw); } catch(e2){}\n      S.seeded = true;\n      setTimeout(() => toast(\"本地数据读取异常，原始数据已保留\"), 900);\n    }\n  } else {\n    try {\n      const old = localStorage.getItem(OLD_KEY);\n      if(old){\n        const o = JSON.parse(old);\n        if(o && Array.isArray(o.entries)){\n          S.entries = o.entries.map(e => ({\n            id: e.id, t: e.t, mode: e.mode, amount: e.amount,\n            note: e.note || \"\", dim: \"wealth\"\n          }));\n          S.colorMode = o.colorMode || \"okx\";\n          S.seeded = true;\n        }\n      }\n    } catch(e){}\n  }\n  if(!S.seeded){\n    seedDemo();\n    S.seeded = true;\n    save();\n  }\n}\n\n/* ============ 演示数据 ============ */\nfunction mulberry32(a){\n  return function(){\n    a |= 0; a = a + 0x6D2B79F5 | 0;\n    let t = Math.imul(a ^ a >>> 15, 1 | a);\n    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;\n    return ((t ^ t >>> 14) >>> 0) / 4294967296;\n  };\n}\n\nfunction seedDemo(){\n  const rnd = mulberry32(20261109);\n  const now = new Date();\n  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());\n  const DAYS = 180;\n  const start = new Date(today.getTime());\n  start.setDate(start.getDate() - (DAYS - 1));\n\n  const list = [];\n  let uid = 1;\n  const add = (t, mode, amount, note, dim) => {\n    t = Math.min(t, Date.now());\n    list.push({\n      id: \"d\" + (uid++), t: Math.round(t), mode: mode,\n      amount: Math.round(amount * 100) / 100, note: note, dim: dim\n    });\n  };\n\n  /* 身价 */\n  add(start.getTime() + 9*3600e3, \"absolute\", 680000, \"初始身价\", \"wealth\");\n  let phase = 0;\n  for(let i = 0; i < DAYS; i++){\n    const d = new Date(start.getTime());\n    d.setDate(d.getDate() + i);\n    if(i === 0) continue;\n    const day = d.getDate();\n    if(day === 1) phase = (phase + 1) % 6;\n\n    if(day === 15) add(d.getTime() + (10 + rnd()*2)*3600e3, \"delta\", 26500 + rnd()*4500, \"工资到账\", \"wealth\");\n    if(day === 5)  add(d.getTime() + (11 + rnd())*3600e3, \"delta\", -5600, \"房租\", \"wealth\");\n\n    const cnt = rnd() < 0.4 ? 2 : 1;\n    for(let k = 0; k < cnt; k++){\n      const notes = [\"日常消费\",\"吃饭\",\"交通\",\"购物\",\"咖啡\",\"外卖\",\"话费\",\"聚会\"];\n      add(d.getTime() + (9 + rnd()*12)*3600e3, \"delta\", -(90 + rnd()*1400),\n          notes[Math.floor(rnd()*notes.length)], \"wealth\");\n    }\n    if(rnd() < 0.13) add(d.getTime() + (14 + rnd()*6)*3600e3, \"delta\", 900 + rnd()*7600, \"理财收益\", \"wealth\");\n\n    const dd = (phase === 2 || phase === 4);\n    if(dd && rnd() < 0.22) add(d.getTime() + (15 + rnd()*5)*3600e3, \"delta\", -(3000 + rnd()*14000), \"行情回撤\", \"wealth\");\n    if(!dd && rnd() < 0.02) add(d.getTime() + (15 + rnd()*5)*3600e3, \"delta\", -(6000 + rnd()*16000), \"大额支出\", \"wealth\");\n    if(rnd() < 0.025) add(d.getTime() + (16 + rnd()*4)*3600e3, \"delta\", 6000 + rnd()*26000, \"副业收入\", \"wealth\");\n  }\n  for(let i = 5; i >= 1; i--){\n    const d = new Date(today.getTime());\n    d.setDate(d.getDate() - i);\n    add(d.getTime() + 20*3600e3, \"delta\", 11000 + rnd()*4200, \"项目回款\", \"wealth\");\n  }\n  add(Date.now() - 40*60e3, \"delta\", 3200, \"理财收益\", \"wealth\");\n\n  /* 成长 */\n  const studyNotes = [\"读书 30 页\",\"英语听力\",\"写代码 2 小时\",\"健身 1 小时\",\"课程学习\",\"写作练习\",\"复盘总结\"];\n  for(let i = 0; i < DAYS; i++){\n    const d = new Date(start.getTime());\n    d.setDate(d.getDate() + i);\n    if(rnd() < 0.72){\n      add(d.getTime() + (19 + rnd()*3)*3600e3, \"delta\", Math.round(15 + rnd()*55),\n          studyNotes[Math.floor(rnd()*studyNotes.length)], \"growth\");\n    }\n    if(rnd() < 0.06) add(d.getTime() + 22*3600e3, \"delta\", 200, \"读完一本书\", \"growth\");\n  }\n\n  /* 心情 */\n  for(let i = 0; i < DAYS; i++){\n    const d = new Date(start.getTime());\n    d.setDate(d.getDate() + i);\n    if(rnd() < 0.82){\n      const dow = d.getDay();\n      const weekend = (dow === 0 || dow === 6);\n      let m = 6.4 + (weekend ? 1.3 : 0) + (rnd() - 0.5) * 3.4;\n      m = clamp(Math.round(m * 2) / 2, 2, 10);\n      add(d.getTime() + (21 + rnd()*2)*3600e3, \"absolute\", m, \"\", \"mood\");\n    }\n  }\n\n  /* 健康 */\n  const hNotes = [\"睡够 7 小时\",\"跑步 3km\",\"早睡\",\"有点累\",\"状态很好\"];\n  for(let i = 0; i < DAYS; i++){\n    const d = new Date(start.getTime());\n    d.setDate(d.getDate() + i);\n    if(rnd() < 0.6){\n      let h = 6.8 + (rnd() - 0.45) * 3.6;\n      h = clamp(Math.round(h * 2) / 2, 2, 10);\n      add(d.getTime() + (22 + rnd()) * 3600e3, \"absolute\", h,\n          hNotes[Math.floor(rnd()*hNotes.length)], \"health\");\n    }\n  }\n\n  /* 持仓演示：黄金 / BTC / 茅台 / 日常用品，45 天行情快照 */\n  const A_DAYS = 45;\n  const aStart = new Date(today.getTime());\n  aStart.setDate(aStart.getDate() - (A_DAYS - 1));\n  let g1 = 845, b1 = 478000, m1 = 1420;\n  for(let i = 0; i < A_DAYS; i++){\n    const d = new Date(aStart.getTime());\n    d.setDate(d.getDate() + i);\n    g1 += (rnd() - 0.42) * 7;\n    b1 += (rnd() - 0.45) * 16000;\n    m1 += (rnd() - 0.5) * 32;\n    g1 = Math.max(800, g1); b1 = Math.max(440000, b1); m1 = Math.max(1350, m1);\n    const total = 120 * g1 + 0.12 * b1 + 50 * m1 + 20 * 6;\n    add(d.getTime() + 15*3600e3, \"absolute\", total, \"行情同步\", \"assets\");\n  }\n  S.assets = [\n    { id:\"as1\", kind:\"gold\",   name:\"黄金\",     code:\"pax-gold\", qty:120,  price:Math.round(g1*100)/100, t:Date.now()-1800e3 },\n    { id:\"as2\", kind:\"crypto\", name:\"比特币\",   code:\"bitcoin\",  qty:0.12, price:Math.round(b1*100)/100, t:Date.now()-1800e3 },\n    { id:\"as3\", kind:\"stock\",  name:\"贵州茅台\", code:\"sh600519\", qty:50,   price:Math.round(m1*100)/100, t:Date.now()-1800e3 },\n    { id:\"as4\", kind:\"goods\",  name:\"大米\",     code:\"\",         qty:20,   price:6, unit:\"袋\", t:Date.now()-1800e3 }\n  ];\n  S.lastSync = Date.now() - 1800e3;\n\n  list.sort((a, b) => a.t - b.t);\n  S.entries = list;\n}\n\n/* ============ 计算 ============ */\nfunction entriesOf(dimKey){\n  return S.entries\n    .filter(e => (e.dim || \"wealth\") === dimKey)\n    .sort((a, b) => a.t - b.t);\n}\n\n/* 序列缓存：draw 每帧都会取当前板块的序列，真实数据不变时没必要重复排序 */\nlet ptsCache = {};\nfunction ptsCacheClear(){ ptsCache = {}; }\nfunction entriesStamp(dimKey){\n  const a = S.entries;\n  return dimKey + \"#\" + a.length + \"#\" +\n         (a.length ? a[0].id + \"/\" + a[a.length-1].id : \"-\");\n}\nfunction computePoints(dimKey){\n  const stamp = entriesStamp(dimKey);\n  const c = ptsCache[dimKey];\n  if(c && c.stamp === stamp) return c.pts;\n\n  const arr = entriesOf(dimKey);\n  let v = 0;\n  const out = [];\n  for(const e of arr){\n    v = (e.mode === \"absolute\") ? e.amount : v + e.amount;\n    out.push({ t: e.t, v: v, e: e });\n  }\n  ptsCache[dimKey] = { stamp: stamp, pts: out };\n  return out;\n}\n\nfunction keyOf(ts, g){\n  const p = PMAP[g];\n  if(p && p.ms > 0) return \"B\" + Math.floor(ts / p.ms);\n  const d = new Date(ts);\n  if(g === \"month\") return d.getFullYear() + \"-\" + d.getMonth();\n  if(g === \"week\"){\n    const t = new Date(d.getFullYear(), d.getMonth(), d.getDate());\n    const dow = (t.getDay() + 6) % 7;\n    t.setDate(t.getDate() - dow);\n    return \"W\" + t.getTime();\n  }\n  return d.getFullYear() + \"-\" + d.getMonth() + \"-\" + d.getDate();\n}\nfunction labelOf(ts, g){\n  const d = new Date(ts);\n  const p = PMAP[g];\n  if(p && p.ms > 0){\n    if(p.ms < 3600e3){\n      const base = pad2(d.getHours()) + \":\" + pad2(d.getMinutes());\n      return (p.ms < 60e3) ? base + \":\" + pad2(d.getSeconds()) : base;\n    }\n    return pad2(d.getMonth()+1) + \"/\" + pad2(d.getDate()) + \" \" + pad2(d.getHours()) + \"时\";\n  }\n  if(g === \"month\") return d.getFullYear() + \"/\" + (d.getMonth() + 1);\n  return pad2(d.getMonth()+1) + \"/\" + pad2(d.getDate());\n}\n\nlet candles = [];\nlet maCache = { m5: [], m10: [], m30: [] };\n\nfunction rebuild(){\n  let pts = computePoints(curDim);\n  const st = simStore[curDim];\n  if(sim.on && st && st.ticks.length){\n    pts = pts.concat(st.ticks);\n    pts.sort((a, b) => a.t - b.t);\n  }\n  if(!pts.length){ candles = []; maCache = { m5:[], m10:[], m30:[] }; return; }\n\n  const buckets = [];\n  let cur = null;\n  for(const p of pts){\n    const k = keyOf(p.t, gran);\n    if(!cur || cur.key !== k){ cur = { key: k, t0: p.t, pts: [] }; buckets.push(cur); }\n    cur.pts.push(p);\n    cur.t = p.t;\n  }\n\n  let prevClose = null;\n  candles = buckets.map((b, i) => {\n    const vals = b.pts.map(p => p.v);\n    const close = vals[vals.length - 1];\n    const open = (i === 0) ? vals[0] : prevClose;\n    let hi = Math.max(open, close), lo = Math.min(open, close);\n    for(const v of vals){ if(v > hi) hi = v; if(v < lo) lo = v; }\n    /* 只保证极端小的值（如刚记第一笔 0→x）也能画出可见实体，\n       不再按价位比例撑大，否则横盘小十字会被强行撑成大蜡烛 */\n    const minBody = Math.max(Math.abs(close) * 0.0002, 0.03);\n    if(hi - lo < minBody){ const pd = minBody / 2; hi += pd; lo -= pd; }\n    let vol = 0;\n    for(const p of b.pts){\n      if(p.e && p.e.mode !== \"absolute\") vol += Math.abs(p.e.amount || 0);\n    }\n    vol += Math.abs(close - open);\n    prevClose = close;\n    return { t: b.t0, o: open, h: hi, l: lo, c: close, v: vol, label: labelOf(b.t0, gran) };\n  });\n\n  const ma = (n) => {\n    const out = new Array(candles.length).fill(null);\n    let sum = 0;\n    for(let i = 0; i < candles.length; i++){\n      sum += candles[i].c;\n      if(i >= n) sum -= candles[i-n].c;\n      if(i >= n-1) out[i] = sum / n;\n    }\n    return out;\n  };\n  maCache = { m5: ma(5), m10: ma(10), m30: ma(30) };\n}\n\n/* ============ 格式化 ============ */\nfunction dim(){ return DMAP[curDim]; }\nfunction fmtVal(v){\n  const k = dim().kind;\n  if(k === \"money\") return fmtMoney(v);\n  if(k === \"points\") return fmtMoney(v, 0);\n  return (Math.round(v * 10) / 10).toFixed(1);\n}\nfunction fmtAxis(v, step){\n  const k = dim().kind;\n  if(k === \"money\"){\n    if(Math.abs(v) >= 1e8) return (v/1e8).toFixed(2) + \"亿\";\n    if(Math.abs(v) >= 1e4) return (v/1e4).toFixed(1) + \"万\";\n    /* 近端聚焦后刻度间距可能很小，按步长保留小数位避免相邻刻度重合 */\n    const dec = !step || step >= 1 ? 0 : (step >= 0.1 ? 1 : 2);\n    return v.toFixed(dec);\n  }\n  if(k === \"points\") return v >= 10000 ? (v/1000).toFixed(1) + \"k\" : Math.round(v);\n  return (Math.round(v * 10) / 10).toFixed(1);\n}\nfunction fmtDelta(v){\n  const k = dim().kind;\n  const s = (k === \"money\") ? fmtMoney(Math.abs(v))\n          : (k === \"points\" ? fmtMoney(Math.abs(v), 0) : Math.abs(v).toFixed(1));\n  return (v > 0 ? \"+\" : (v < 0 ? \"−\" : \"\")) + s;\n}\n/* 实时价专用的高精度格式：横盘跳动时末位要能看见变化 */\nfunction fmtLive(v){\n  const k = dim().kind;\n  if(k === \"money\"){\n    const a = Math.abs(v);\n    if(a >= 1e8) return (v / 1e8).toFixed(3) + \"亿\";\n    if(a >= 1e7) return (v / 1e4).toFixed(2) + \"万\";\n    return fmtMoney(v, 2);\n  }\n  if(k === \"points\") return fmtMoney(v, 0);\n  return (Math.round(v * 10) / 10).toFixed(1);\n}\n\n/* ============ K 线 ============ */\nconst canvas = $(\"#chart\");\nconst ctx = canvas.getContext(\"2d\");\nconst wrap = $(\"#chartWrap\");\nlet W = 0, H = 0;\n\n/* shift 为像素级平移量：0 = 最新 K 线贴右边界，\n   正值 = 往回看历史，负值 = 把最新 K 线往左拖、右侧留白（欧易样式） */\nconst view = { count: 46, shift: 0 };\nconst cursor = { active: false, x: 0, y: 0 };\nlet C = { up: \"#0ecb81\", down: \"#f6465d\" };\nconst GRID = \"rgba(255,255,255,.042)\";\nconst AXIS = \"#5b646e\";\n\nfunction syncColors(){\n  C.up = S.colorMode === \"cn\" ? \"#f6465d\" : \"#0ecb81\";\n  C.down = S.colorMode === \"cn\" ? \"#0ecb81\" : \"#f6465d\";\n  const rs = document.documentElement.style;\n  rs.setProperty(\"--up\", C.up);\n  rs.setProperty(\"--down\", C.down);\n  rs.setProperty(\"--accent\", dim().color);\n}\n\nlet raf = 0;\nfunction requestDraw(){\n  if(raf) return;\n  raf = requestAnimationFrame(() => { raf = 0; draw(); });\n}\nfunction roundRect(c, x, y, w, h, r){\n  r = Math.min(r, h/2, w/2);\n  c.beginPath();\n  c.moveTo(x+r, y); c.lineTo(x+w-r, y);\n  c.quadraticCurveTo(x+w, y, x+w, y+r);\n  c.lineTo(x+w, y+h-r);\n  c.quadraticCurveTo(x+w, y+h, x+w-r, y+h);\n  c.lineTo(x+r, y+h);\n  c.quadraticCurveTo(x, y+h, x, y+h-r);\n  c.lineTo(x, y+r);\n  c.quadraticCurveTo(x, y, x+r, y);\n  c.closePath();\n}\nfunction niceStep(range, target){\n  const raw = range / target;\n  const mag = Math.pow(10, Math.floor(Math.log10(raw)));\n  const norm = raw / mag;\n  let step;\n  if(norm <= 1) step = 1;\n  else if(norm <= 2) step = 2;\n  else if(norm <= 2.5) step = 2.5;\n  else if(norm <= 5) step = 5;\n  else step = 10;\n  return step * mag;\n}\n\nfunction draw(){\n  if(!W || !H) return;\n  ctx.clearRect(0, 0, W, H);\n  ctx.fillStyle = \"#0b0e11\";\n  ctx.fillRect(0, 0, W, H);\n\n  const padL = 11, padR = 58, padT = 30, padB = 20, gapY = 13;\n  const plotW = W - padL - padR;\n\n  if(!candles.length){\n    ctx.fillStyle = \"#39434d\";\n    ctx.font = \"12px system-ui, -apple-system, sans-serif\";\n    ctx.textAlign = \"center\";\n    ctx.textBaseline = \"middle\";\n    ctx.fillText(\"还没有\" + dim().name + \"记录\", W/2, H/2 - 8);\n    ctx.fillStyle = \"#2d353d\";\n    ctx.fillText(\"点下方按钮记下第一笔\", W/2, H/2 + 14);\n    updateHud(-1);\n    return;\n  }\n\n  const total = candles.length;\n  const count = view.count;\n  const space = plotW / count;\n  const lastIdx = total - 1;\n\n  /* 平移范围（像素）：正 = 往回看历史，负 = 把最新 K 线往左拖、右侧留白 */\n  const maxBack = Math.max(0, total - count) * space;\n  const maxFwd  = (total > count) ? Math.min(total, count) * space * 0.7 : 0;\n  view.shift = clamp(view.shift, -maxFwd, maxBack);\n  const shift = view.shift;\n\n  /* 统一坐标：i = lastIdx 时贴右边界；shift 为像素平移量（跟手，不按格跳） */\n  const xI = i => padL + plotW - (lastIdx - i) * space - space * 0.5 + shift;\n\n  const end = clamp(Math.round(total - shift / space), 0, total);\n  const start = Math.max(0, end - count - 2);\n\n  /* 可见窗口全部蜡烛的 hi/lo（全历史范围） */\n  let fHi = -Infinity, fLo = Infinity;\n  for(let i = start; i < end; i++){\n    const k = candles[i];\n    if(k.h > fHi) fHi = k.h;\n    if(k.l < fLo) fLo = k.l;\n  }\n  if(!isFinite(fHi) || !isFinite(fLo)){ fHi = 1; fLo = 0; }\n  /* 近端聚焦缩放（真实行情观感）：\n     以最近 14 根可见蜡烛的波动为主范围，更早的大幅蜡烛只向外扩到\n     近端中枢 ± 近端跨度的 3 倍，再大的历史波动被裁剪出屏。\n     否则刚记过一笔大额后，整张图会被压扁成一条横线。\n     最近 14 根永远完整可见（cap 由近端范围推出，必然覆盖它们）*/\n  const rN = Math.min(14, end - start);\n  let rHi = -Infinity, rLo = Infinity;\n  for(let i = Math.max(start, end - rN); i < end; i++){\n    const k = candles[i];\n    if(k.h > rHi) rHi = k.h;\n    if(k.l < rLo) rLo = k.l;\n  }\n  if(!isFinite(rHi) || !isFinite(rLo)){ rHi = fHi; rLo = fLo; }\n  const rMid = (rHi + rLo) / 2;\n  const rSpan = Math.max(rHi - rLo, Math.abs(rMid) * 0.0012, 0.6);\n  let hi = Math.min(fHi, rMid + rSpan * 3);\n  let lo = Math.max(fLo, rMid - rSpan * 3);\n  if(hi <= lo){ hi = fHi; lo = fLo; }\n  const pad = (hi - lo) * 0.14 || Math.abs(hi) * 0.02 || 1;\n  hi += pad;\n  lo = Math.max(0, lo - pad);\n  const range = (hi - lo) || 1;\n\n  const volH = Math.max(28, (H - padT - padB) * 0.17);\n  const mainH = H - padT - padB - volH - gapY;\n  const mainTop = padT;\n  const mainBot = mainTop + mainH;\n  const volTop = mainBot + gapY;\n  const volBot = volTop + volH;\n\n  const yP = p => mainTop + (hi - p) / range * mainH;\n\n  /* y 轴网格 + 价格刻度 */\n  ctx.font = \"10px ui-monospace, 'SF Mono', Menlo, monospace\";\n  ctx.textBaseline = \"middle\";\n  const step = niceStep(range, 5);\n  const first = Math.ceil(lo / step) * step;\n  for(let p = first; p <= hi; p += step){\n    const y = Math.round(yP(p)) + 0.5;\n    if(y < mainTop - 1 || y > mainBot + 1) continue;\n    ctx.strokeStyle = GRID;\n    ctx.lineWidth = 1;\n    ctx.beginPath(); ctx.moveTo(padL, y); ctx.lineTo(W - padR, y); ctx.stroke();\n    ctx.fillStyle = AXIS;\n    ctx.textAlign = \"left\";\n    ctx.fillText(fmtAxis(p, step), W - padR + 7, clamp(y, mainTop + 6, mainBot - 6));\n  }\n\n  /* ===== 裁剪：K 线元素只在绘图区内出现，滑出屏幕的部分自然消失 ===== */\n  ctx.save();\n  ctx.beginPath();\n  ctx.rect(padL, mainTop - 2, plotW, volBot + 17 - mainTop + 2);\n  ctx.clip();\n\n  /* x 轴竖网格 + 时间标签 */\n  const every = Math.max(1, Math.ceil(64 / space));\n  ctx.textAlign = \"center\";\n  for(let i = start; i < end; i++){\n    if(i % every !== 0) continue;\n    const x = Math.round(xI(i)) + 0.5;\n    ctx.strokeStyle = \"rgba(255,255,255,.028)\";\n    ctx.beginPath(); ctx.moveTo(x, mainTop); ctx.lineTo(x, volBot); ctx.stroke();\n    ctx.fillStyle = AXIS;\n    ctx.fillText(candles[i].label, x, volBot + 11);\n  }\n\n  /* 十字光标列高亮 */\n  let ci = -1;\n  if(cursor.active){\n    ci = clamp(Math.round(lastIdx - (padL + plotW + shift - space * 0.5 - cursor.x) / space),\n               start, Math.max(start, end - 1));\n    const hx = xI(ci);\n    ctx.fillStyle = \"rgba(255,255,255,.045)\";\n    ctx.fillRect(hx - space / 2, mainTop, space, volBot - mainTop);\n  }\n\n  let maxV = 0;\n  for(let i = start; i < end; i++) if(candles[i].v > maxV) maxV = candles[i].v;\n  maxV = maxV || 1;\n  const bw = Math.max(1, Math.min(space * 0.7, 26));\n  for(let i = start; i < end; i++){\n    const k = candles[i];\n    const up = k.c >= k.o;\n    const h = Math.max(1, (k.v / maxV) * volH * 0.86);\n    const x = xI(i);\n    ctx.fillStyle = (up ? C.up : C.down) + \"6b\";\n    ctx.fillRect(Math.round(x - bw/2), Math.round(volBot - h), Math.round(bw), Math.round(h));\n  }\n  ctx.strokeStyle = \"rgba(255,255,255,.05)\";\n  ctx.beginPath(); ctx.moveTo(padL, Math.round(volBot) + 0.5); ctx.lineTo(W - padR, Math.round(volBot) + 0.5); ctx.stroke();\n\n  const drawMA = (arr, color) => {\n    ctx.beginPath();\n    let started = false;\n    for(let i = start; i < end; i++){\n      const v = arr[i];\n      if(v === null || v === undefined){ started = false; continue; }\n      const x = xI(i), y = yP(v);\n      if(!started){ ctx.moveTo(x, y); started = true; }\n      else ctx.lineTo(x, y);\n    }\n    ctx.strokeStyle = color;\n    ctx.lineWidth = 1.15;\n    ctx.lineJoin = \"round\";\n    ctx.stroke();\n  };\n  drawMA(maCache.m30, \"#5b8def\");\n  drawMA(maCache.m10, \"#c77dff\");\n  drawMA(maCache.m5,  \"#f7c948\");\n\n  for(let i = start; i < end; i++){\n    const k = candles[i];\n    const up = k.c >= k.o;\n    const col = up ? C.up : C.down;\n    const x = xI(i);\n    const xr = Math.round(x) + 0.5;\n    ctx.strokeStyle = col;\n    ctx.lineWidth = Math.max(1, Math.min(1.6, bw * 0.22));\n    ctx.beginPath();\n    ctx.moveTo(xr, Math.round(yP(k.h)) + 0.5);\n    ctx.lineTo(xr, Math.round(yP(k.l)) + 0.5);\n    ctx.stroke();\n    const yo = yP(k.o), yc = yP(k.c);\n    ctx.fillStyle = col;\n    ctx.fillRect(x - bw/2, Math.min(yo, yc), bw, Math.max(1.2, Math.abs(yc - yo)));\n  }\n\n  /* 目标线 */\n  const tgt = S.targets[curDim];\n  if(tgt && tgt > 0 && tgt >= lo && tgt <= hi){\n    const y = Math.round(yP(tgt)) + 0.5;\n    ctx.save();\n    ctx.setLineDash([5, 4]);\n    ctx.strokeStyle = \"rgba(247,201,72,.7)\";\n    ctx.lineWidth = 1;\n    ctx.beginPath(); ctx.moveTo(padL, y); ctx.lineTo(W - padR, y); ctx.stroke();\n    ctx.restore();\n    ctx.font = \"9px ui-monospace, monospace\";\n    ctx.fillStyle = \"rgba(247,201,72,.85)\";\n    ctx.textAlign = \"left\"; ctx.textBaseline = \"middle\";\n    ctx.fillText(\"目标\", padL + 2, y - 7);\n  }\n\n  /* 最新价：虚线 + 呼吸点（标签要画在裁剪区外） */\n  const liveX = xI(lastIdx);\n  let liveLab = null;\n  if(liveX >= padL - space * 1.5 && liveX <= padL + plotW + space * 1.5){\n    const k = candles[lastIdx];\n    const baseC = candles[lastIdx-1] ? candles[lastIdx-1].c : k.o;\n    const col = (k.c >= baseC) ? C.up : C.down;\n    const simLive = sim.on && simStore[curDim] && simStore[curDim].ticks.length > 0;\n    const y = Math.round(yP(k.c)) + 0.5;\n\n    ctx.save();\n    ctx.setLineDash([3, 3]);\n    ctx.strokeStyle = col;\n    ctx.globalAlpha = 0.6;\n    ctx.lineWidth = 1;\n    ctx.beginPath(); ctx.moveTo(padL, y); ctx.lineTo(W - padR, y); ctx.stroke();\n    ctx.restore();\n\n    if(simLive){\n      const ph = 0.5 + 0.5 * Math.sin(Date.now() / 260);\n      ctx.beginPath();\n      ctx.arc(clamp(liveX, padL + 1, padL + plotW - 1), y, 2.6 + 1.1 * ph, 0, Math.PI * 2);\n      ctx.fillStyle = col; ctx.fill();\n    }\n    liveLab = { y: y, col: col, text: fmtAxis(k.c), live: simLive };\n  }\n\n  /* 十字光标：线、圆点在裁剪区内 */\n  let curInfo = null;\n  if(cursor.active){\n    const k = candles[ci];\n    const cx = Math.round(xI(ci)) + 0.5;\n    const cy = clamp(cursor.y, mainTop, volBot);\n\n    ctx.save();\n    ctx.setLineDash([4, 4]);\n    ctx.strokeStyle = \"rgba(160,172,184,.55)\";\n    ctx.lineWidth = 1;\n    ctx.beginPath(); ctx.moveTo(cx, mainTop); ctx.lineTo(cx, volBot); ctx.stroke();\n    ctx.beginPath(); ctx.moveTo(padL, Math.round(cy) + 0.5); ctx.lineTo(W - padR, Math.round(cy) + 0.5); ctx.stroke();\n    ctx.restore();\n\n    ctx.fillStyle = \"#dfe6ee\";\n    ctx.beginPath(); ctx.arc(cx, Math.round(cy) + 0.5, 2.5, 0, Math.PI*2); ctx.fill();\n    curInfo = { cx: cx, cy: cy, label: k.label, inMain: cy <= mainBot };\n  }\n\n  ctx.restore();\n  /* ===== 裁剪结束 ===== */\n\n  /* 最新价标签（钉在右轴） */\n  if(liveLab){\n    ctx.font = \"600 10px ui-monospace, 'SF Mono', Menlo, monospace\";\n    const tw = ctx.measureText(liveLab.text).width;\n    const bw2 = Math.max(tw + 12, padR - 6);\n    ctx.save();\n    if(liveLab.live){\n      const ph = 0.5 + 0.5 * Math.sin(Date.now() / 260);\n      ctx.shadowColor = liveLab.col;\n      ctx.shadowBlur = 5 + 9 * ph;\n    }\n    roundRect(ctx, W - padR + 2, liveLab.y - 9, bw2, 18, 3);\n    ctx.fillStyle = liveLab.col; ctx.fill();\n    ctx.restore();\n    ctx.fillStyle = \"#0b0e11\";\n    ctx.textAlign = \"left\"; ctx.textBaseline = \"middle\";\n    ctx.fillText(liveLab.text, W - padR + 8, liveLab.y + 0.5);\n  }\n\n  /* 十字光标标签 */\n  if(curInfo){\n    if(curInfo.inMain){\n      const price = hi - (curInfo.cy - mainTop) / mainH * range;\n      const lab = fmtAxis(price);\n      ctx.font = \"600 10px ui-monospace, 'SF Mono', Menlo, monospace\";\n      const tw = ctx.measureText(lab).width;\n      const w2 = Math.max(tw + 12, padR - 6);\n      roundRect(ctx, W - padR + 2, curInfo.cy - 9, w2, 18, 3);\n      ctx.fillStyle = \"#2a3138\"; ctx.fill();\n      ctx.fillStyle = \"#dfe6ee\";\n      ctx.textAlign = \"left\"; ctx.textBaseline = \"middle\";\n      ctx.fillText(lab, W - padR + 8, curInfo.cy + 0.5);\n    }\n    const tl = curInfo.label;\n    ctx.font = \"600 10px ui-monospace, 'SF Mono', Menlo, monospace\";\n    const tw2 = ctx.measureText(tl).width;\n    const bx = clamp(curInfo.cx - tw2/2 - 7, padL, W - padR - tw2 - 14);\n    roundRect(ctx, bx, volBot + 1, tw2 + 14, 16, 3);\n    ctx.fillStyle = \"#2a3138\"; ctx.fill();\n    ctx.fillStyle = \"#dfe6ee\";\n    ctx.textAlign = \"center\"; ctx.textBaseline = \"middle\";\n    ctx.fillText(tl, bx + (tw2 + 14)/2, volBot + 9);\n  }\n\n  if(cursor.active && ci >= 0) updateHud(ci);\n  else updateHud(lastIdx);\n  heroConverge();\n}\n\nconst hudEl = $(\"#hud\");\nlet lastHudKey = \"\";\nlet lastLiveValue = null;\nfunction updateHud(idx){\n  if(idx < 0 || !candles[idx]){ hudEl.innerHTML = \"\"; lastHudKey = \"\"; lastLiveValue = null; return; }\n  const k = candles[idx];\n  const prev = candles[idx-1];\n  const base = prev ? prev.c : k.o;\n  const chg = k.c - base;\n  const pct = base ? (chg / base * 100) : 0;\n  const cls = chg > 0 ? \"up\" : (chg < 0 ? \"down\" : \"\");\n\n  /* 现价 = 最后一根 K 线的收盘价（横盘模拟会持续刷新它） */\n  const lastC = candles[candles.length - 1].c;\n  const livePrev = candles.length > 1 ? candles[candles.length - 2].c : candles[0].o;\n  const liveChg = lastC - livePrev;\n  const livePct = livePrev ? (liveChg / livePrev * 100) : 0;\n  const liveCls = liveChg > 0 ? \"up\" : (liveChg < 0 ? \"down\" : \"\");\n  const beat = (lastLiveValue !== null && lastC !== lastLiveValue)\n    ? (lastC > lastLiveValue ? \"beat-up\" : \"beat-down\") : \"\";\n  lastLiveValue = lastC;\n\n  const key = curDim + gran + idx + \"|\" + chg + \"|\" + lastC + \"|\" + cls;\n  if(key === lastHudKey) return;\n  lastHudKey = key;\n\n  const timeTxt = gran === \"month\"\n    ? (new Date(k.t).getFullYear() + \"/\" + (new Date(k.t).getMonth()+1))\n    : dstr(k.t);\n  const f = v => (v === null || v === undefined) ? \"--\" : fmtAxis(v);\n  const isScore = dim().kind === \"score\";\n\n  hudEl.innerHTML =\n    '<div class=\"live\">' +\n      '<span class=\"dot ' + liveCls + '\"><\/span>' +\n      '<span class=\"num ' + liveCls + ' ' + beat + '\">' + fmtLive(lastC) + '<\/span>' +\n      '<span class=\"pct ' + liveCls + '\">' + (liveChg >= 0 ? \"+\" : \"\") + livePct.toFixed(2) + '%<\/span>' +\n    '<\/div>' +\n    '<div class=\"r\"><span class=\"k\">' + timeTxt + '<\/span>' +\n      '<span class=\"k\">开<\/span><span class=\"v\">' + f(k.o) + '<\/span>' +\n      '<span class=\"k\">高<\/span><span class=\"v\">' + f(k.h) + '<\/span>' +\n      '<span class=\"k\">低<\/span><span class=\"v\">' + f(k.l) + '<\/span>' +\n      '<span class=\"k\">收<\/span><span class=\"v ' + cls + '\">' + f(k.c) + '<\/span>' +\n    '<\/div>' +\n    '<div class=\"r\"><span class=\"k\">' + (isScore ? \"变化\" : \"涨跌\") + '<\/span><span class=\"v ' + cls + '\">' +\n      fmtDelta(chg) + ' (' + (chg >= 0 ? \"+\" : \"\") + pct.toFixed(2) + '%)<\/span>' +\n    '<\/div>' +\n    '<div class=\"ma\">' +\n      '<b style=\"color:#f7c948\">MA5 ' + f(maCache.m5[idx]) + '<\/b>' +\n      '<b style=\"color:#c77dff\">MA10 ' + f(maCache.m10[idx]) + '<\/b>' +\n      '<b style=\"color:#5b8def\">MA30 ' + f(maCache.m30[idx]) + '<\/b>' +\n    '<\/div>';\n}\n\nfunction resize(){\n  const r = wrap.getBoundingClientRect();\n  const dpr = Math.min(window.devicePixelRatio || 1, 2.5);\n  W = Math.max(1, r.width);\n  H = Math.max(1, r.height);\n  canvas.width = Math.round(W * dpr);\n  canvas.height = Math.round(H * dpr);\n  canvas.style.width = W + \"px\";\n  canvas.style.height = H + \"px\";\n  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n  draw();\n}\n\n/* ============ 手势（欧易式：像素跟手 + 惯性 + 锚点缩放） ============ */\nconst pointers = new Map();\nlet drag = null, pinch = null, inertia = 0;\nconst LONGPRESS_MS = 300;\nconst MAX_COUNT = 260, MIN_COUNT = 12;\n\nfunction padW(){ return Math.max(1, W - 11 - 58); }\nfunction plotSpace(){ return padW() / Math.max(1, view.count); }\n\n/* 当前平移允许范围（像素） */\nfunction shiftBounds(){\n  const space = plotSpace();\n  const total = candles.length;\n  const back = Math.max(0, total - view.count) * space;              /* 往回看历史 */\n  const fwd  = (total > view.count) ? Math.min(total, view.count) * space * 0.7 : 0; /* 右侧留白 */\n  return { min: -fwd, max: back, space: space, plotW: padW() };\n}\nfunction clampShift(v){\n  const b = shiftBounds();\n  return clamp(v, b.min, b.max);\n}\n/* 屏幕 x（画布内坐标）对应的浮点 K 线索引 */\nfunction indexAtX(px){\n  const b = shiftBounds();\n  const lastIdx = candles.length - 1;\n  return lastIdx - (11 + b.plotW - b.space * 0.5 + view.shift - px) / b.space;\n}\n/* 让 i0 这根 K 线停在 px 处，反解 shift */\nfunction shiftForAnchor(px, i0){\n  const b = shiftBounds();\n  const lastIdx = candles.length - 1;\n  return px - 11 - b.plotW + b.space * 0.5 + (lastIdx - i0) * b.space;\n}\n\nfunction stopInertia(){\n  if(inertia){ cancelAnimationFrame(inertia); inertia = 0; }\n}\nfunction startInertia(v){\n  stopInertia();\n  if(!isFinite(v) || Math.abs(v) < 0.06) return;\n  let vel = v;\n  const step = () => {\n    vel *= 0.935;\n    if(Math.abs(vel) < 0.015){ inertia = 0; return; }\n    const b = shiftBounds();\n    const next = clamp(view.shift + vel * 16, b.min, b.max);\n    if(next === view.shift){ inertia = 0; return; }   /* 到边界即停 */\n    view.shift = next;\n    draw();\n    inertia = requestAnimationFrame(step);\n  };\n  inertia = requestAnimationFrame(step);\n}\n\nlet edgeRaf = 0;\nfunction stopEdgeScroll(){\n  if(edgeRaf){ cancelAnimationFrame(edgeRaf); edgeRaf = 0; }\n}\n/* 长按十字光标时，把手指拖到绘图区左右边缘可自动滚动翻看历史（欧易式） */\nfunction startEdgeScroll(){\n  stopEdgeScroll();\n  const step = () => {\n    if(!drag || !drag.pressed || !cursor.active){ edgeRaf = 0; return; }\n    const pw = padW(), margin = 44;\n    let v = 0;\n    if(cursor.x < 11 + margin) v = -((11 + margin - cursor.x) / margin) * 7;\n    else if(cursor.x > 11 + pw - margin) v = ((cursor.x - (11 + pw - margin)) / margin) * 7;\n    if(v){\n      const next = clampShift(view.shift - v);\n      if(next !== view.shift){\n        view.shift = next;\n        draw();\n      }\n    }\n    edgeRaf = requestAnimationFrame(step);\n  };\n  edgeRaf = requestAnimationFrame(step);\n}\n\ncanvas.addEventListener(\"pointerdown\", e => {\n  resetIdle();\n  stopInertia();\n  stopEdgeScroll();\n  try { canvas.setPointerCapture(e.pointerId); } catch(err){}\n  pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });\n  if(pointers.size === 1){\n    drag = {\n      x0: e.clientX, y0: e.clientY, off: view.shift,\n      moved: false, pressed: false,\n      lastX: e.clientX, lastT: performance.now(), v: 0\n    };\n    drag.timer = setTimeout(() => {\n      if(drag && !drag.moved){\n        drag.pressed = true;\n        const r = canvas.getBoundingClientRect();\n        cursor.active = true;\n        cursor.x = e.clientX - r.left;\n        cursor.y = e.clientY - r.top;\n        if(navigator.vibrate){ try { navigator.vibrate(12); } catch(err){} }\n        requestDraw();\n      }\n    }, LONGPRESS_MS);\n    pinch = null;\n  } else if(pointers.size === 2){\n    if(drag && drag.timer) clearTimeout(drag.timer);\n    const ps = [...pointers.values()];\n    const r = canvas.getBoundingClientRect();\n    const midX = (ps[0].x + ps[1].x) / 2 - r.left;\n    pinch = {\n      d0: Math.hypot(ps[0].x - ps[1].x, ps[0].y - ps[1].y),\n      c0: view.count,\n      midX: midX,\n      i0: indexAtX(midX)\n    };\n    drag = null;\n  }\n});\n\ncanvas.addEventListener(\"pointermove\", e => {\n  if(!pointers.has(e.pointerId)) return;\n  pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });\n\n  if(pointers.size === 2 && pinch){\n    const ps = [...pointers.values()];\n    const d = Math.hypot(ps[0].x - ps[1].x, ps[0].y - ps[1].y);\n    if(pinch.d0 > 0 && d > 0){\n      const nc = clamp(Math.round(pinch.c0 * (pinch.d0 / d)), MIN_COUNT, MAX_COUNT);\n      if(nc !== view.count){\n        view.count = nc;\n        view.shift = clampShift(shiftForAnchor(pinch.midX, pinch.i0));\n        draw();\n      }\n    }\n    return;\n  }\n\n  if(drag){\n    const dx = e.clientX - drag.x0;\n    const dy = e.clientY - drag.y0;\n    if(drag.pressed){\n      /* 长按中：光标跟随手指，不平移；靠近边缘自动滚动 */\n      const r = canvas.getBoundingClientRect();\n      cursor.active = true;\n      cursor.x = e.clientX - r.left;\n      cursor.y = e.clientY - r.top;\n      if(!edgeRaf) startEdgeScroll();\n      requestDraw();\n      return;\n    }\n    if(!drag.moved && (Math.abs(dx) > 5 || Math.abs(dy) > 5)){\n      drag.moved = true;\n      if(drag.timer) clearTimeout(drag.timer);\n    }\n    if(drag.moved){\n      const now = performance.now();\n      const dt = now - drag.lastT;\n      if(dt > 0){\n        const inst = (e.clientX - drag.lastX) / dt;\n        drag.v = drag.v * 0.55 + inst * 0.45;\n        drag.lastX = e.clientX;\n        drag.lastT = now;\n      }\n      view.shift = clampShift(drag.off + dx);\n      cursor.active = false;\n      draw();\n    }\n    return;\n  }\n\n  if(e.pointerType === \"mouse\"){\n    const r = canvas.getBoundingClientRect();\n    cursor.active = true;\n    cursor.x = e.clientX - r.left;\n    cursor.y = e.clientY - r.top;\n    requestDraw();\n  }\n});\n\nfunction endPointer(e){\n  if(!pointers.has(e.pointerId)) return;\n  const wasSingle = pointers.size === 1;\n  pointers.delete(e.pointerId);\n  if(pointers.size === 0){\n    stopEdgeScroll();\n    if(drag && drag.timer) clearTimeout(drag.timer);\n    if(drag && drag.pressed && wasSingle){\n      /* 长按结束：十字光标保留，轻点别处可取消 */\n      requestDraw();\n    } else if(drag && drag.moved && wasSingle){\n      startInertia(drag.v * 0.85);\n    } else if(drag && !drag.moved && wasSingle){\n      const r = canvas.getBoundingClientRect();\n      const x = e.clientX - r.left, y = e.clientY - r.top;\n      if(!cursor.active || Math.abs(cursor.x - x) > 6 || Math.abs(cursor.y - y) > 6){\n        cursor.active = true; cursor.x = x; cursor.y = y;\n      } else {\n        cursor.active = false;\n      }\n      requestDraw();\n    }\n    drag = null; pinch = null;\n  }\n  if(pointers.size < 2) pinch = null;\n}\ncanvas.addEventListener(\"pointerup\", endPointer);\ncanvas.addEventListener(\"pointercancel\", endPointer);\ncanvas.addEventListener(\"pointerleave\", e => {\n  if(e.pointerType === \"mouse\" && !drag){ cursor.active = false; requestDraw(); }\n});\ncanvas.addEventListener(\"wheel\", e => {\n  e.preventDefault();\n  resetIdle();\n  const r = canvas.getBoundingClientRect();\n  const px = e.clientX - r.left;\n  const i0 = indexAtX(px);\n  const nc = clamp(Math.round(view.count * (e.deltaY > 0 ? 1.14 : 0.877)), MIN_COUNT, MAX_COUNT);\n  if(nc === view.count) return;\n  view.count = nc;\n  view.shift = clampShift(shiftForAnchor(px, i0));\n  draw();\n}, { passive: false });\n\n/* ============ 空闲横盘模拟（不落库，纯渲染层） ============\n   每个维度各自保留横盘数据：切页面 / 交互只是暂停，\n   回来后横盘从上次位置继续，变化不丢失。 */\nconst simStore = {};   /* dim -> { base, cur, ticks: [] } */\nlet sim = { on: false, dim: \"\", timer: 0 };\nlet idleTimer = 0;\n\nfunction simPause(){\n  if(sim.timer){ clearInterval(sim.timer); sim.timer = 0; }\n}\nfunction simStopAll(){\n  simPause();\n  sim.on = false; sim.dim = \"\";\n  for(const k in simStore) delete simStore[k];\n}\nfunction simStart(){\n  if(document.hidden || !S.entries.length) return;\n  /* 持仓板块只走真实行情同步，不做模拟跳动，避免误导 */\n  if(curDim === \"assets\"){ simPause(); sim.on = false; return; }\n  const pts = computePoints(curDim);\n  if(!pts.length){ simPause(); sim.on = false; sim.dim = \"\"; return; }\n  const lv = pts[pts.length-1].v, lt = pts[pts.length-1].t;\n  const st = simStore[curDim];\n  /* 真实数据在横盘期间被更新过（如添加了记录）→ 从新真实值重新开始。\n     ⚠️ 必须同时比对「真实末值是否等于起锚值」：\n     只看时间戳的话，添加记录与上一次 tick 落在同一时刻时不会重建，\n     横盘会继续围着旧基准游走，把刚记进去的值又拉回去（表现为数字来回跳） */\n  const drift = st ? Math.abs(st.base - lv) : 0;\n  const driftTol = Math.max(Math.abs(lv) * 1e-9, 1e-9);\n  if(!st || !st.ticks.length || lt > st.ticks[st.ticks.length-1].t || drift > driftTol){\n    simStore[curDim] = { base: lv, cur: lv, ticks: [] };\n  } else if(sim.dim !== curDim){\n    /* 从别的板块切回来：不要沿用上一条老 tick 的时间基准 */\n    st.base = lv;\n  }\n  sim.on = true; sim.dim = curDim;\n  simPause();\n  sim.timer = setInterval(simTick, 1000);\n}\nfunction simTick(){\n  if(!sim.on) return;\n  /* 正在拖动 K 线或用十字光标查看历史时先别跳，松手立刻继续 */\n  if(drag || cursor.active) return;\n  const st = simStore[sim.dim];\n  if(!st) return;\n  const d = DIMS.find(x => x.key === sim.dim) || DIMS[0];\n  /* 收盘变化保持极小：顶部数字每秒只微跳；\n     真实感来自每根蜡烛的上下影线（见下），不靠收盘大幅游走 */\n  const step = (d.kind === \"score\")\n    ? 0.030\n    : Math.max(st.base * 0.00025, 0.1);\n  st.cur += (Math.random() - 0.5) * 2 * step * 2.0;\n  st.cur += (st.base - st.cur) * 0.08;   /* 均值回归 → 横盘 */\n  if(d.kind === \"score\") st.cur = clamp(st.cur, 1.2, 10.8);\n  else if(st.cur < 0) st.cur = 0;\n  /* 同一秒内推入上影/下影/收盘三个采样点，让横盘蜡烛有真实的影线结构；\n     收盘点必须最后推入（桶内最后一个值 = 收盘价，顶部数字只跟收盘走） */\n  const wick = (d.kind === \"score\") ? 0.08 : Math.max(st.base * 0.0010, 0.3);\n  const now = Date.now();\n  const e0 = { mode: \"sim\", amount: 0 };\n  st.ticks.push({ t: now, v: st.cur + Math.random() * wick * 1.7, e: e0 });\n  st.ticks.push({ t: now, v: st.cur - Math.random() * wick * 1.7, e: e0 });\n  st.ticks.push({ t: now, v: st.cur, e: e0 });\n  /* 横盘历史不用无限堆积：够填满视图即可（含影线采样点，×3） */\n  if(st.ticks.length > 720) st.ticks.splice(0, st.ticks.length - 720);\n  rebuild();\n  draw();\n  if(sim.dim === curDim) heroTick();\n}\nfunction resetIdle(){\n  simPause();                            /* 只暂停，横盘数据保留 */\n  clearTimeout(idleTimer);\n  if(idleTimer){ idleTimer = 0; }\n  simStart();                            /* 不再等待，立刻恢复横盘 */\n}\ndocument.addEventListener(\"visibilitychange\", () => {\n  if(document.hidden){ simPause(); clearTimeout(idleTimer); }\n  else resetIdle();\n});\n\n/* ============ 渲染 ============ */\nfunction renderPeriods(){\n  $(\"#periods\").innerHTML = PERIODS.map(p =>\n    '<button data-g=\"' + p.g + '\" class=\"' + (p.g === gran ? \"on\" : \"\") + '\">' + p.name + \"<\/button>\"\n  ).join(\"\");\n}\n\nfunction renderDims(){\n  $(\"#dims\").innerHTML = DIMS.map(d =>\n    '<button class=\"dim' + (d.key === curDim ? \" on\" : \"\") + '\" data-d=\"' + d.key + '\"' +\n    (d.key === curDim ? ' style=\"color:' + d.color + '\"' : \"\") + '>' +\n    '<i style=\"background:' + d.color + '\"><\/i>' + d.name + '<\/button>'\n  ).join(\"\");\n}\n\nconst shownVals = {};\nlet heroAnim = 0;\n/* 数字过渡动画的序列号：切板块 / 开新动画时递增，\n   过期的动画帧发现序号不符就自我终止 */\nlet heroSeq = 0;\n\n/* ---------- hero 大数字的唯一数据源 ----------\n   期望值只由「当前板块 + 横盘状态」推导，不接受任何外部传入的数值，\n   从根上消除「别处传了个旧值把它覆盖掉」这类问题 */\nfunction heroWant(){\n  const pts = computePoints(curDim);\n  if(!pts.length) return { v: 0, empty: true, pts: pts, last: null };\n  const last = pts[pts.length - 1];\n  const st = simStore[curDim];\n  /* 只有横盘数据比真实数据更新时才用横盘值；\n     否则刚记完一笔会先停在旧数字上，等下一次 tick 才跳变 */\n  /* 三重条件：横盘在跑 + 横盘数据更新 + 横盘基准就是这个板块的真实末值。\n     最后一条是关键——只要真实值改过而锚点还没重建，立刻回落到真实值，\n     绝不让旧的横盘基准把数字拉回去 */\n  const fresh = !!(sim.on && st && st.ticks.length &&\n                   last.t <= st.ticks[st.ticks.length - 1].t &&\n                   Math.abs(st.base - last.v) <= Math.max(Math.abs(last.v) * 1e-9, 1e-9));\n  return { v: fresh ? st.cur : last.v, empty: false, pts: pts, last: last };\n}\n\nfunction paintHeroNum(v){\n  const d = dim();\n  const el = $(\"#heroValue\");\n  if(d.kind === \"money\"){\n    const parts = fmtMoney(v).split(\".\");\n    el.innerHTML = '<span class=\"cur\">¥<\/span>' + parts[0] + '<span class=\"dec\">.' + parts[1] + '<\/span>';\n  } else if(d.kind === \"points\"){\n    el.innerHTML = fmtMoney(v, 0) + '<span class=\"unit\">点<\/span>';\n  } else {\n    el.innerHTML = v.toFixed(1) + '<span class=\"unit\">/10<\/span>';\n  }\n}\n/* 今日基线：真实序列里上一个自然日的末值 */\nfunction todayBaseOf(pts){\n  if(!pts.length) return null;\n  const todayK = dayKey(pts[pts.length-1].t);\n  let base = null;\n  for(let i = pts.length - 1; i >= 0; i--){\n    if(dayKey(pts[i].t) !== todayK){ base = pts[i].v; break; }\n  }\n  return (base === null) ? pts[0].v : base;\n}\n/* 数字 + 今日变化徽章一起刷新（label / 时间戳不在这里动） */\nfunction paintHeroBits(v, pts){\n  paintHeroNum(v);\n  const base = todayBaseOf(pts);\n  const chg = v - base;\n  const pct = base ? chg / base * 100 : 0;\n  const up = chg > 0, down = chg < 0;\n  const chgEl = $(\"#heroChange\");\n  chgEl.className = \"chip \" + (up ? \"up\" : (down ? \"down\" : \"flat\"));\n  chgEl.textContent = fmtDelta(chg) + \"  \" + (up ? \"+\" : \"\") + pct.toFixed(2) + \"% \" + (up ? \"▲\" : (down ? \"▼\" : \"\"));\n}\n\nfunction stopHeroAnim(){\n  if(heroAnim){ cancelAnimationFrame(heroAnim); heroAnim = 0; }\n}\n\n/* 横盘跳动：直接按当前板块重算，不信任任何传入值 */\nfunction heroTick(){\n  const w = heroWant();\n  if(w.empty) return;\n  heroSeq++;\n  stopHeroAnim();\n  shownVals[curDim] = w.v;\n  paintHeroBits(w.v, w.pts);\n}\n\nfunction renderHero(animate){\n  heroSeq++;\n  stopHeroAnim();\n\n  const d = dim();\n  $(\"#heroLabel\").textContent = d.label;\n  const chgEl = $(\"#heroChange\");\n  const subEl = $(\"#heroSub\");\n\n  const w = heroWant();\n  if(w.empty){\n    shownVals[curDim] = 0;\n    paintHeroNum(0);\n    chgEl.className = \"chip flat\";\n    chgEl.textContent = \"--\";\n    subEl.textContent = \"暂无记录\";\n    return;\n  }\n\n  const v = w.v;\n  const from = shownVals[curDim];\n  if(animate && from !== undefined && isFinite(from) && Math.abs(from - v) > 1e-9){\n    const t0 = performance.now();\n    const seq = heroSeq;\n    const toDim = curDim;\n    const step = (now) => {\n      /* 中途切了板块 / 有新渲染 → 立刻退出，绝不把旧维度的数字写回去 */\n      if(seq !== heroSeq || toDim !== curDim){ heroAnim = 0; return; }\n      const t = clamp((now - t0) / 380, 0, 1);\n      const ease = 1 - Math.pow(1 - t, 3);\n      const cur = from + (v - from) * ease;\n      shownVals[toDim] = cur;\n      paintHeroBits(cur, w.pts);\n      if(t < 1) heroAnim = requestAnimationFrame(step);\n      else { heroAnim = 0; shownVals[toDim] = v; paintHeroBits(v, w.pts); }\n    };\n    heroAnim = requestAnimationFrame(step);\n  } else {\n    shownVals[curDim] = v;\n    paintHeroBits(v, w.pts);\n  }\n\n  subEl.textContent = \"今日 · 更新于 \" + dtimeShort(w.last.t);\n}\n\n/* 兜底收敛：每帧核对顶部数字是否等于当前板块的期望值，\n   只要有别的路径（旧动画、旧 tick、异步回调）写过它，下一帧就纠正回来 */\nfunction heroConverge(){\n  if(heroAnim) return;\n  const w = heroWant();\n  if(w.empty) return;\n  const cur = shownVals[curDim];\n  const tol = Math.max(Math.abs(w.v) * 1e-6, 1e-9);\n  if(cur === undefined || !isFinite(cur) || Math.abs(cur - w.v) > tol){\n    shownVals[curDim] = w.v;\n    paintHeroBits(w.v, w.pts);\n  }\n}\n\n/* 顶部数字写入防线：旧壳残余脚本（热更新替换前启动的那套）会持续往\n   #heroValue 写旧板块的值。MutationObserver 监听被外部改动，立刻按\n   当前板块纠正——旧写入最多存活一帧，不再与用户可见值交替 */\n(function(){\n  const el = document.getElementById(\"heroValue\");\n  const chg = document.getElementById(\"heroChange\");\n  if(!el || typeof MutationObserver === \"undefined\") return;\n  let lock = false, lastFix = 0;\n  function guardWrite(){\n    lock = true;\n    try{\n      const w = heroWant();\n      if(w.empty) return;\n      shownVals[curDim] = w.v;\n      paintHeroBits(w.v, w.pts);\n    }catch(e){}\n    finally{ lock = false; }\n  }\n  function onMut(){\n    if(lock) return;\n    const now = Date.now();\n    if(now - lastFix < 120) return;    /* 防抖：与旧写入者互搏时限频 */\n    lastFix = now;\n    try{\n      const w = heroWant();\n      const cur = shownVals[curDim];\n      const tol = Math.max(Math.abs(w.v || 1) * 1e-6, 1e-9);\n      if(w.empty || cur === undefined || !isFinite(cur) || Math.abs(cur - w.v) > tol){\n        guardWrite();\n      }\n    }catch(e){}\n  }\n  const mo = new MutationObserver(onMut);\n  mo.observe(el, { childList: true, characterData: true, subtree: true });\n  if(chg) mo.observe(chg, { childList: true, characterData: true, subtree: true });\n})();\n\nfunction calcStreak(){\n  const set = new Set(S.entries.map(e => dayKey(e.t)));\n  if(!set.size) return 0;\n  const d = new Date();\n  d.setHours(0, 0, 0, 0);\n  if(!set.has(dayKey(d.getTime()))) d.setDate(d.getDate() - 1);\n  let n = 0;\n  while(set.has(dayKey(d.getTime())) && n < 9999){\n    n++;\n    d.setDate(d.getDate() - 1);\n  }\n  return n;\n}\n\nfunction renderStats(){\n  const cs = candles;\n  const rp = computePoints(curDim);\n  const v = rp.length ? rp[rp.length-1].v : 0;\n  const tgt = S.targets[curDim] || 0;\n\n  if(tgt > 0 && v > 0){\n    const pct = clamp(v / tgt * 100, 0, 100);\n    const tgtTxt = (dim().kind === \"money\") ? fmtShort(tgt) : fmtVal(tgt);\n    $(\"#stGoal\").innerHTML = Math.round(pct) + '%<small>/ ' + tgtTxt + '<\/small>';\n    $(\"#stBar\").style.width = pct.toFixed(1) + \"%\";\n  } else {\n    $(\"#stGoal\").textContent = \"--\";\n    $(\"#stBar\").style.width = \"0%\";\n  }\n\n  const pc = PMAP[gran] || PMAP.day;\n  let text = \"--\", ratio = 0, sign = 0;\n  if(cs.length >= 2){\n    const idx = Math.max(0, cs.length - 1 - pc.back);\n    const base = cs[idx].c;\n    const diff = v - base;\n    const pct = base ? (diff / base * 100) : 0;\n    text = (dim().kind === \"score\") ? fmtDelta(diff) : ((diff >= 0 ? \"+\" : \"−\") + Math.abs(pct).toFixed(1) + \"%\");\n    ratio = clamp(Math.abs(pct) / 20 * 100, 4, 100);\n    sign = diff > 0 ? 1 : (diff < 0 ? -1 : 0);\n    $(\"#stChgBar\").style.background = (diff >= 0) ? C.up : C.down;\n  }\n  $(\"#stChgLab\").textContent = pc.chg;\n  $(\"#stChg\").textContent = text;\n  $(\"#stChg\").style.color = sign > 0 ? C.up : (sign < 0 ? C.down : \"var(--text)\");\n  $(\"#stChgBar\").style.width = ratio.toFixed(0) + \"%\";\n\n  const st = calcStreak();\n  $(\"#stStreak\").innerHTML = st + \"<small>天<\/small>\";\n  $(\"#stStreakBar\").style.width = clamp(st / 30 * 100, 0, 100).toFixed(0) + \"%\";\n}\n\nfunction renderLedger(){\n  if(curDim === \"assets\"){ renderAssets(); return; }\n  const list = $(\"#ledgerList\");\n  const pts = computePoints(curDim);\n  $(\"#ledgerTitle\").textContent = dim().name + \"明细\";\n  $(\"#ledgerCount\").textContent = pts.length + \" 笔\";\n\n  if(!pts.length){\n    list.innerHTML = '<div class=\"empty\">还没有' + dim().name + '记录<br/>点下方按钮记下第一笔<\/div>';\n    return;\n  }\n\n  const arr = pts.slice().reverse();\n  const kind = dim().kind;\n  let html = \"\";\n  for(const p of arr){\n    const e = p.e;\n    const isSet = e.mode === \"absolute\";\n    const amt = e.amount;\n    const cls = isSet ? \"set\" : (amt >= 0 ? \"up\" : \"down\");\n    const icon = isSet ? \"=\" : (amt >= 0 ? \"+\" : \"−\");\n    let title = (e.note && e.note.trim()) ? e.note\n      : (isSet ? ((kind === \"score\") ? dim().name + \"记录\" : \"设定\") : (amt >= 0 ? \"增加\" : \"减少\"));\n\n    let amtText;\n    if(isSet) amtText = (kind === \"score\") ? amt.toFixed(1) : fmtVal(amt);\n    else amtText = (amt >= 0 ? \"+\" : \"−\") + (kind === \"money\" ? fmtMoney(Math.abs(amt)) : fmtMoney(Math.abs(amt), 0));\n\n    html +=\n      '<div class=\"li\">' +\n        '<div class=\"li-ico ' + (isSet ? \"\" : cls) + '\">' + icon + '<\/div>' +\n        '<div class=\"li-main\">' +\n          '<div class=\"li-title\">' + escapeHtml(title) + '<\/div>' +\n          '<div class=\"li-time\">' + dtimeShort(e.t) + '<\/div>' +\n        '<\/div>' +\n        '<div class=\"li-right\">' +\n          '<div class=\"li-amt ' + cls + '\">' + amtText + '<\/div>' +\n          '<div class=\"li-total\">余 ' + fmtVal(p.v) + '<\/div>' +\n        '<\/div>' +\n        '<button class=\"li-del\" data-del=\"' + e.id + '\">×<\/button>' +\n      '<\/div>';\n  }\n  list.innerHTML = html;\n}\n\nfunction updateDock(){\n  const btnAdd = $(\"#btnAdd\"), btnSub = $(\"#btnSub\");\n  if(curDim === \"assets\"){\n    btnSub.style.display = \"\"; btnSub.textContent = \"⟳ 刷新行情\";\n    btnAdd.textContent = \"＋ 添加商品\";\n  } else if(curDim === \"wealth\"){\n    btnSub.style.display = \"\"; btnAdd.textContent = \"＋ 增加\"; btnSub.textContent = \"− 减少\";\n  } else if(curDim === \"growth\"){\n    btnSub.style.display = \"\"; btnAdd.textContent = \"＋ 记录成长\"; btnSub.textContent = \"− 扣减\";\n  } else {\n    btnSub.style.display = \"none\"; btnAdd.textContent = \"＋ 记录\" + dim().name;\n  }\n}\n\nfunction chartFadeIn(){\n  canvas.classList.remove(\"fade-in\");\n  void canvas.offsetWidth;\n  canvas.classList.add(\"fade-in\");\n}\n\nfunction renderAll(animate){\n  ptsCacheClear();\n  syncColors();\n  rebuild();\n  renderPeriods();\n  renderDims();\n  renderHero(animate);\n  renderStats();\n  renderLedger();\n  updateDock();\n  draw();\n}\n\n/* ============ 面板 ============ */\nconst sheetEdit = $(\"#sheetEdit\");\nconst sheetStats = $(\"#sheetStats\");\nconst sheetSet = $(\"#sheetSet\");\nconst sheetAsset = $(\"#sheetAsset\");\nconst mask = $(\"#mask\");\n\nfunction openSheet(el){ resetIdle(); mask.classList.add(\"on\"); el.classList.add(\"on\"); }\nfunction closeSheets(){\n  mask.classList.remove(\"on\");\n  sheetEdit.classList.remove(\"on\");\n  sheetStats.classList.remove(\"on\");\n  sheetSet.classList.remove(\"on\");\n  sheetAsset.classList.remove(\"on\");\n}\nmask.addEventListener(\"click\", closeSheets);\n\nlet editMode = \"add\";\nlet editDim = \"wealth\";\nlet moodValue = 0;\n\nfunction openEdit(mode, dimKey){\n  const dk = dimKey || curDim;\n  if(dk === \"assets\"){ openAssetForm(); return; }\n  editDim = dk;\n  const d = DMAP[editDim];\n  editMode = (d.kind === \"score\") ? \"set\" : mode;\n  moodValue = 0;\n  $(\"#amount\").value = \"\";\n  $(\"#note\").value = \"\";\n  renderEditPanel();\n  openSheet(sheetEdit);\n  if(d.kind !== \"score\") setTimeout(() => { try { $(\"#amount\").focus(); } catch(err){} }, 260);\n}\n\nfunction renderEditPanel(){\n  const d = DMAP[editDim];\n\n  $(\"#sheetTitle\").textContent = (d.kind === \"score\")\n    ? \"今天\" + d.name + \"怎么样？\"\n    : (editMode === \"add\" ? \"增加\" + d.name : (editMode === \"sub\" ? \"减少\" + d.name : \"设定\" + d.name));\n\n  $(\"#dimPicker\").innerHTML = DIMS.map(x =>\n    '<button data-d=\"' + x.key + '\" class=\"' + (x.key === editDim ? \"on\" : \"\") + '\">' + x.name + '<\/button>'\n  ).join(\"\");\n\n  if(d.kind === \"score\"){\n    $(\"#panelNum\").style.display = \"none\";\n    $(\"#panelMood\").style.display = \"\";\n    $(\"#modes\").style.display = \"none\";\n    renderMoods();\n    $(\"#confirmBtn\").textContent = \"记录\" + d.name;\n  } else {\n    $(\"#panelNum\").style.display = \"\";\n    $(\"#panelMood\").style.display = \"none\";\n    $(\"#modes\").style.display = \"\";\n    $(\"#amountCur\").textContent = (d.kind === \"money\") ? \"¥\" : \"\";\n    $(\"#amount\").placeholder = (d.kind === \"money\") ? \"0.00\" : \"0\";\n    $(\"#quick\").innerHTML = d.quick.map(v =>\n      '<button data-v=\"' + v + '\">' + (v >= 10000 ? (v/10000) + \"万\" : fmtMoney(v, 0)) + \"<\/button>\"\n    ).join(\"\");\n    document.querySelectorAll(\"#modes button\").forEach(b => b.classList.toggle(\"on\", b.dataset.m === editMode));\n    $(\"#confirmBtn\").textContent = \"确认\";\n  }\n\n  const pts = computePoints(editDim);\n  const cur = pts.length ? pts[pts.length-1].v : 0;\n  $(\"#sheetTip\").textContent = \"当前\" + d.name + \" \" + (d.kind === \"money\" ? \"¥\" : \"\") + fmtVal(cur);\n}\n\nfunction renderMoods(){\n  $(\"#moods\").innerHTML = MOODS.map((m, i) => {\n    const col = MOOD_COLORS[i];\n    const on = (moodValue === m.v);\n    const style = on\n      ? 'color:' + col + ';background:color-mix(in srgb,' + col + ' 12%,#0f1215);border-color:' + col + '55;'\n      : '';\n    return '<button class=\"mood' + (on ? \" sel\" : \"\") + '\" data-v=\"' + m.v + '\" style=\"' + style + '\">' +\n           faceSVG(m.face) + '<span>' + m.t + '<\/span><\/button>';\n  }).join(\"\");\n}\n\n$(\"#moods\").addEventListener(\"click\", e => {\n  const b = e.target.closest(\".mood\");\n  if(!b) return;\n  moodValue = parseFloat(b.dataset.v);\n  renderMoods();\n  $(\"#confirmBtn\").textContent = \"记为 \" + moodValue.toFixed(1) + \" 分\";\n});\n\n$(\"#dimPicker\").addEventListener(\"click\", e => {\n  const b = e.target.closest(\"button\");\n  if(!b) return;\n  editDim = b.dataset.d;\n  if(DMAP[editDim].kind === \"score\") editMode = \"set\";\n  else if(editMode === \"set\") editMode = \"add\";\n  renderEditPanel();\n});\n\ndocument.querySelectorAll(\"#modes button\").forEach(b => {\n  b.addEventListener(\"click\", () => {\n    editMode = b.dataset.m;\n    document.querySelectorAll(\"#modes button\").forEach(x => x.classList.toggle(\"on\", x === b));\n    renderEditPanel();\n  });\n});\n\n$(\"#quick\").addEventListener(\"click\", e => {\n  const b = e.target.closest(\"button\");\n  if(!b) return;\n  $(\"#amount\").value = b.dataset.v;\n});\n\n$(\"#confirmBtn\").addEventListener(\"click\", () => {\n  const d = DMAP[editDim];\n  let mode, amount;\n  let note = $(\"#note\").value.trim();\n\n  if(d.kind === \"score\"){\n    if(!moodValue){ toast(\"先选一个状态\"); return; }\n    mode = \"absolute\";\n    amount = moodValue;\n    if(!note){\n      const idx = MOODS.findIndex(m => m.v === moodValue);\n      if(idx >= 0) note = MOODS[idx].t;\n    }\n  } else {\n    const num = parseFloat(String($(\"#amount\").value).replace(/[^\\d.]/g, \"\"));\n    if(!isFinite(num) || num <= 0){ toast(\"请输入有效数值\"); return; }\n    if(editMode === \"set\"){ mode = \"absolute\"; amount = num; }\n    else if(editMode === \"sub\"){ mode = \"delta\"; amount = -num; }\n    else { mode = \"delta\"; amount = num; }\n  }\n\n  S.entries.push({\n    id: \"u\" + Date.now() + Math.random().toString(36).slice(2, 6),\n    t: Date.now(), mode: mode,\n    amount: Math.round(amount * 100) / 100,\n    note: note, dim: editDim\n  });\n  save();\n\n  curDim = editDim;\n  /* 不重置视图：添加后保持用户当前查看的位置。\n     若正在回看历史，平移一格抵消新增的 K 线，画面内容不跳动。 */\n  const keepHist = view.shift > 0.5;\n  closeSheets();\n  resetIdle();               /* 先以新真实值重建横盘锚点，再渲染 → 顶部数字直接滚到新值 */\n  renderAll(true);\n  if(keepHist) view.shift = clampShift(view.shift + plotSpace());\n  draw();\n  checkAchievements();\n  resetIdle();\n\n  const unit = (d.kind === \"money\") ? \"¥\" : \"\";\n  toast(d.kind === \"score\"\n    ? \"已记录\" + d.name + \" \" + amount.toFixed(1) + \" 分\"\n    : \"已记录\" + d.name + \" \" + unit + fmtMoney(amount, d.kind === \"money\" ? 2 : 0));\n});\n\n$(\"#amount\").addEventListener(\"keydown\", e => {\n  if(e.key === \"Enter\"){ e.preventDefault(); $(\"#confirmBtn\").click(); }\n});\n\n$(\"#btnAdd\").addEventListener(\"click\", () => openEdit(\"add\"));\n$(\"#btnSub\").addEventListener(\"click\", () => {\n  if(curDim === \"assets\"){ syncQuotes(true); } else { openEdit(\"sub\"); }\n});\n\n$(\"#dims\").addEventListener(\"click\", e => {\n  const b = e.target.closest(\".dim\");\n  if(!b) return;\n  if(b.dataset.d === curDim){ openEdit(\"add\", b.dataset.d); return; }\n  curDim = b.dataset.d;\n  view.shift = 0;\n  view.count = (gran === \"day\") ? (DMAP[curDim].kind === \"score\" ? 40 : 46) : (gran === \"week\" ? 40 : 24);\n  resetIdle();\n  chartFadeIn();\n  renderAll();\n});\n\n$(\"#periods\").addEventListener(\"click\", e => {\n  const b = e.target.closest(\"button\");\n  if(!b) return;\n  gran = b.dataset.g;\n  view.shift = 0;\n  view.count = PMAP[gran] ? PMAP[gran].count : 46;\n  resetIdle();\n  chartFadeIn();\n  renderAll();\n});\n\n$(\"#ledgerList\").addEventListener(\"click\", e => {\n  const editBtn = e.target.closest(\"[data-editasset]\");\n  if(editBtn && !e.target.closest(\".li-del\")){\n    const aid = editBtn.dataset.editasset;\n    const a = S.assets.find(x => x.id === aid);\n    if(!a) return;\n    const v = prompt(\"修改「\" + a.name + \"」的单价（元）\", String(a.price || \"\"));\n    if(v === null) return;\n    const p = parseFloat(String(v).replace(/[^\\d.]/g, \"\"));\n    if(!isFinite(p) || p <= 0){ toast(\"单价无效\"); return; }\n    a.price = p; a.t = Date.now();\n    const now = Date.now();\n    S.entries.push({\n      id: \"a\" + now, t: now, mode: \"absolute\",\n      amount: Math.round(assetsValue() * 100) / 100,\n      note: \"手动改价\", dim: \"assets\"\n    });\n    save();\n    renderAll();\n    toast(\"单价已更新为 ¥\" + fmtMoney(p));\n    return;\n  }\n  const delAsset = e.target.closest(\"[data-delasset]\");\n  if(delAsset){\n    const aid = delAsset.dataset.delasset;\n    if(!confirm(\"确定删除这个商品吗？持仓 K 线的历史快照会保留。\")) return;\n    S.assets = S.assets.filter(x => x.id !== aid);\n    save();\n    renderAll();\n    toast(\"已删除\");\n    return;\n  }\n  const btn = e.target.closest(\".li-del\");\n  if(!btn) return;\n  const id = btn.dataset.del;\n  const i = S.entries.findIndex(x => x.id === id);\n  if(i < 0) return;\n  if(!confirm(\"确定删除这条记录吗？\")) return;\n  S.entries.splice(i, 1);\n  save();\n  renderAll();\n  toast(\"已删除\");\n});\n\n/* ============ 统计面板 ============ */\nconst ACHIEVEMENTS = [\n  { id:\"first\",   ic:\"🌱\", nm:\"第一步\" },\n  { id:\"week\",    ic:\"🔥\", nm:\"七日之约\" },\n  { id:\"month\",   ic:\"🏔️\", nm:\"三十天\" },\n  { id:\"rich\",    ic:\"📈\", nm:\"复利\" },\n  { id:\"million\", ic:\"💎\", nm:\"百万身价\" },\n  { id:\"moody\",   ic:\"🌈\", nm:\"心情晴天\" },\n  { id:\"learner\", ic:\"📚\", nm:\"成长者\" },\n  { id:\"all\",     ic:\"🧭\", nm:\"全能选手\" }\n];\n\nfunction renderStatsSheet(){\n  let html = \"\";\n  for(const d of DIMS){\n    const pts = computePoints(d.key);\n    if(!pts.length){\n      html += '<div class=\"ov-row\"><i style=\"background:' + d.color + '\"><\/i>' +\n              '<span class=\"n\">' + d.name + '<\/span>' +\n              '<span class=\"v\" style=\"color:#4e5862\">--<\/span><\/div>';\n      continue;\n    }\n    const first = pts[0].v, last = pts[pts.length-1].v;\n    const diff = last - first;\n    if(d.kind === \"money\" || d.kind === \"points\"){\n      const pct = first ? (diff / first * 100) : 0;\n      const cTxt = (d.kind === \"points\")\n        ? fmtDelta(diff)\n        : ((diff >= 0 ? \"+\" : \"\") + pct.toFixed(1) + \"%\");\n      html += '<div class=\"ov-row\"><i style=\"background:' + d.color + '\"><\/i>' +\n              '<span class=\"n\">' + d.name + '<\/span>' +\n              '<span class=\"v\">' + (d.kind === \"money\" ? \"¥\" : \"\") + fmtMoney(last, d.kind === \"money\" ? 2 : 0) + '<\/span>' +\n              '<span class=\"c\" style=\"color:' + (diff >= 0 ? C.up : C.down) + '\">' + cTxt + '<\/span><\/div>';\n    } else {\n      const avg = pts.reduce((s, p) => s + p.v, 0) / pts.length;\n      html += '<div class=\"ov-row\"><i style=\"background:' + d.color + '\"><\/i>' +\n              '<span class=\"n\">' + d.name + '<\/span>' +\n              '<span class=\"v\">' + last.toFixed(1) + '<\/span>' +\n              '<span class=\"c\">均值 ' + avg.toFixed(1) + '<\/span><\/div>';\n    }\n  }\n  $(\"#overview\").innerHTML = html;\n\n  const weeks = 13;\n  const today = new Date(); today.setHours(0, 0, 0, 0);\n  const endDay = new Date(today.getTime());\n  const dow = (endDay.getDay() + 6) % 7;\n  endDay.setDate(endDay.getDate() + (6 - dow));\n  const startDay = new Date(endDay.getTime());\n  startDay.setDate(startDay.getDate() - (weeks * 7 - 1));\n\n  const counts = {};\n  for(const e of S.entries){\n    const k = dayKey(e.t);\n    counts[k] = (counts[k] || 0) + 1;\n  }\n\n  let hh = \"\";\n  for(let w = 0; w < weeks; w++){\n    hh += '<div class=\"heat-col\">';\n    for(let k = 0; k < 7; k++){\n      const d = new Date(startDay.getTime());\n      d.setDate(d.getDate() + w * 7 + k);\n      const c = counts[dayKey(d.getTime())] || 0;\n      let bg = \"#1a1f25\";\n      if(c === 1) bg = \"rgba(14,203,129,.28)\";\n      else if(c === 2) bg = \"rgba(14,203,129,.55)\";\n      else if(c >= 3) bg = \"rgba(14,203,129,.85)\";\n      if(d.getTime() > today.getTime()) bg = \"transparent\";\n      hh += '<div class=\"heat-cell\" style=\"background:' + bg + '\"><\/div>';\n    }\n    hh += \"<\/div>\";\n  }\n  $(\"#heat\").innerHTML = hh;\n\n  renderBadges();\n}\n\nfunction renderBadges(){\n  const list = S.achievements || [];\n  $(\"#badges\").innerHTML = ACHIEVEMENTS.map(a =>\n    '<div class=\"badge' + (list.indexOf(a.id) >= 0 ? \" on\" : \"\") + '\">' +\n      '<div class=\"ic\">' + a.ic + '<\/div><div class=\"nm\">' + a.nm + '<\/div><\/div>'\n  ).join(\"\");\n}\n\nfunction unlock(id, name){\n  S.achievements = S.achievements || [];\n  if(S.achievements.indexOf(id) >= 0) return;\n  S.achievements.push(id);\n  save();\n  toast(\"🏆 解锁成就：\" + name);\n}\n\nfunction checkAchievements(){\n  if(!S.entries.length) return;\n  unlock(\"first\", \"第一步\");\n\n  const st = calcStreak();\n  if(st >= 7) unlock(\"week\", \"七日之约\");\n  if(st >= 30) unlock(\"month\", \"三十天\");\n\n  const wp = computePoints(\"wealth\");\n  if(wp.length){\n    const v = wp[wp.length-1].v;\n    if(v >= 500000) unlock(\"rich\", \"复利\");\n    if(v >= 1000000) unlock(\"million\", \"百万身价\");\n  }\n\n  const gp = computePoints(\"growth\");\n  if(gp.length && gp[gp.length-1].v >= 1000) unlock(\"learner\", \"成长者\");\n\n  const happy = entriesOf(\"mood\").filter(e => e.mode === \"absolute\" && e.amount >= 8);\n  if(happy.length >= 5) unlock(\"moody\", \"心情晴天\");\n\n  const usedDims = new Set(S.entries.map(e => e.dim || \"wealth\"));\n  if(usedDims.size >= 4) unlock(\"all\", \"全能选手\");\n}\n\n$(\"#btnStats\").addEventListener(\"click\", () => {\n  renderStatsSheet();\n  openSheet(sheetStats);\n});\n\n/* ============ 持仓行情 ============ */\nfunction assetsValue(){\n  let s = 0;\n  for(const a of S.assets){\n    if(a.price && isFinite(a.price)) s += a.qty * a.price;\n  }\n  return s;\n}\n\n/* ---------- 行情源（国内网络可直连） ---------- */\n/* 加密/黄金 → gate.io；股票/指数/港股 → 腾讯行情(script 注入绕跨域)；汇率 → er-api */\nconst GATE_PAIRS = {\n  bitcoin:\"BTC_USDT\", ethereum:\"ETH_USDT\", solana:\"SOL_USDT\", dogecoin:\"DOGE_USDT\",\n  binancecoin:\"BNB_USDT\", ripple:\"XRP_USDT\", cardano:\"ADA_USDT\", tron:\"TRX_USDT\",\n  litecoin:\"LTC_USDT\", polkadot:\"DOT_USDT\", \"shiba-inu\":\"SHIB_USDT\", avalanche:\"AVAX_USDT\",\n  chainlink:\"LINK_USDT\", \"bitcoin-cash\":\"BCH_USDT\", uniswap:\"UNI_USDT\", cosmos:\"ATOM_USDT\",\n  \"pax-gold\":\"PAXG_USDT\"\n};\nfunction gatePair(code){\n  const c = String(code || \"\").toLowerCase();\n  if(GATE_PAIRS[c]) return GATE_PAIRS[c];\n  const up = String(code || \"\").toUpperCase().replace(/[^A-Z0-9]/g, \"\");\n  return up ? up + \"_USDT\" : \"\";\n}\nasync function gatePrice(pair){\n  if(!pair) return null;\n  const r = await fetch(\"https://api.gateio.ws/api/v4/spot/tickers?currency_pair=\" +\n    encodeURIComponent(pair) + \"&_=\" + Date.now());\n  const j = await r.json();\n  const v = (j && j[0]) ? parseFloat(j[0].last) : NaN;\n  return (isFinite(v) && v > 0) ? v : null;\n}\nfunction loadScript(url, ms){\n  return new Promise((resolve, reject) => {\n    const s = document.createElement(\"script\");\n    s.src = url;\n    s.onload = () => resolve(true);\n    s.onerror = () => reject(new Error(\"load\"));\n    document.head.appendChild(s);\n    setTimeout(() => reject(new Error(\"timeout\")), ms || 8000);\n  });\n}\nasync function tencentQuotes(codes){\n  const uniq = [...new Set(codes.map(c => String(c).toLowerCase()))];\n  const out = {};\n  if(!uniq.length) return out;\n  try {\n    await loadScript(\"https://qt.gtimg.cn/q=\" + uniq.join(\",\") + \"&_=\" + Date.now(), 8000);\n  } catch(e){}\n  for(const c of uniq){\n    const raw = window[\"v_\" + c];\n    if(typeof raw === \"string\"){\n      const f = raw.split(\"~\");\n      const p = parseFloat(f[3]);\n      if(isFinite(p) && p > 0) out[c] = p;\n    }\n  }\n  return out;\n}\nasync function fetchFx(){\n  try {\n    const r = await fetch(\"https://open.er-api.com/v6/latest/USD\");\n    const j = await r.json();\n    if(j && j.rates && j.rates.CNY){\n      S.usdCny = j.rates.CNY;\n      if(j.rates.HKD) S.hkdCny = j.rates.CNY / j.rates.HKD;\n      S.fxT = Date.now();\n      return true;\n    }\n  } catch(e){}\n  return false;\n}\n\nlet syncing = false;\nasync function syncQuotes(manual){\n  if(syncing) return;\n  if(!S.assets.length){ if(manual) toast(\"先添加一个商品\"); return; }\n  const net = S.assets.filter(a => a.kind !== \"goods\");\n  if(!net.length){\n    if(manual) toast(\"日常用品是手动单价，无需联网\");\n    return;\n  }\n  syncing = true;\n  if(manual) toast(\"正在获取行情…\");\n  let okCount = 0;\n\n  const needFx = net.some(a => a.kind === \"crypto\" || a.kind === \"gold\" || /^(us|hk)/i.test(a.code || \"\"));\n  if(needFx) await fetchFx();\n\n  const stocks = net.filter(a => a.kind === \"stock\");\n  let tq = {};\n  if(stocks.length) tq = await tencentQuotes(stocks.map(a => a.code));\n\n  const now = Date.now();\n  for(const a of net){\n    try {\n      if(a.kind === \"crypto\"){\n        const p = await gatePrice(gatePair(a.code));\n        if(p){ a.price = p * (S.usdCny || 7.2); a.t = now; okCount++; }\n      } else if(a.kind === \"gold\"){\n        const p = await gatePrice(\"PAXG_USDT\");\n        if(p){ a.price = p * (S.usdCny || 7.2) / 31.1035; a.t = now; okCount++; }\n      } else if(a.kind === \"stock\"){\n        const p = tq[String(a.code).toLowerCase()];\n        if(p){\n          let v = p;\n          if(/^us/i.test(a.code)) v = p * (S.usdCny || 7.2);\n          else if(/^hk/i.test(a.code)) v = p * (S.hkdCny || 0.86);\n          a.price = v; a.t = now; okCount++;\n        }\n      }\n    } catch(e){}\n  }\n  save();\n\n  if(okCount > 0){\n    const total = Math.round(assetsValue() * 100) / 100;\n    S.entries.push({\n      id: \"a\" + now, t: now, mode: \"absolute\",\n      amount: total, note: \"行情同步\", dim: \"assets\"\n    });\n    S.lastSync = now;\n    save();\n  }\n  renderAll();\n  syncing = false;\n  if(manual) toast(okCount > 0\n    ? \"已更新 \" + okCount + \"/\" + net.length + \" 项行情\"\n    : \"暂时取不到行情，请检查网络后重试\");\n}\n\nfunction renderAssets(){\n  const list = $(\"#ledgerList\");\n  $(\"#ledgerTitle\").textContent = \"我的持仓\";\n  $(\"#ledgerCount\").textContent = S.assets.length\n    ? \"总市值 ¥\" + fmtMoney(assetsValue(), 0)\n    : \"0 项\";\n  if(!S.assets.length){\n    list.innerHTML = '<div class=\"empty\">还没有添加商品<br/>投资品自动联网估值 · 日常用品填单价即可<\/div>';\n    return;\n  }\n  const total = assetsValue();\n  const KIND_NAME = { crypto:\"加密币\", stock:\"股票\", gold:\"黄金\", goods:\"日常\" };\n  let html = \"\";\n  for(const a of S.assets){\n    const val = a.qty * (a.price || 0);\n    const pct = total > 0 ? val / total * 100 : 0;\n    let priceTxt, tTxt, unitTxt;\n    if(a.kind === \"goods\"){\n      unitTxt = \" \" + (a.unit || \"件\");\n      priceTxt = \"¥\" + fmtMoney(a.price) + \" / \" + (a.unit || \"件\") + \" · 手动\";\n      tTxt = \"点卡片可改单价\";\n    } else {\n      unitTxt = (a.kind === \"gold\") ? \"克\" : \"\";\n      priceTxt = a.price\n        ? ((a.kind === \"gold\") ? \"¥\" + fmtMoney(a.price) + \" /克\" : \"¥\" + fmtMoney(a.price, a.price < 10 ? 4 : 2))\n        : \"未获取\";\n      tTxt = a.t ? dtimeShort(a.t) : \"--\";\n    }\n    html +=\n      '<div class=\"li\"' + (a.kind === \"goods\" ? ' data-editasset=\"' + a.id + '\"' : '') + '>' +\n        '<div class=\"li-ico\" style=\"color:#c77dff;background:color-mix(in srgb,#c77dff 12%,transparent)\">◆<\/div>' +\n        '<div class=\"li-main\">' +\n          '<div class=\"li-title\">' + escapeHtml(a.name) +\n            ' <span style=\"color:#4e5862;font-size:10px\">' + KIND_NAME[a.kind] + \" · \" + a.qty + unitTxt + '<\/span><\/div>' +\n          '<div class=\"li-time\">' + priceTxt + \" · \" + tTxt + '<\/div>' +\n        '<\/div>' +\n        '<div class=\"li-right\">' +\n          '<div class=\"li-amt set\">¥' + fmtMoney(val, 0) + '<\/div>' +\n          '<div class=\"li-total\">' + pct.toFixed(1) + '%<\/div>' +\n        '<\/div>' +\n        '<button class=\"li-del\" data-delasset=\"' + a.id + '\">×<\/button>' +\n      '<\/div>';\n  }\n  list.innerHTML = html;\n}\nlet assetKindSel = \"crypto\";\nconst ASSET_PRESETS = {\n  crypto: [\n    { name:\"比特币\", code:\"bitcoin\" },\n    { name:\"以太坊\", code:\"ethereum\" },\n    { name:\"SOL\",    code:\"solana\" },\n    { name:\"狗狗币\", code:\"dogecoin\" },\n    { name:\"BNB\",    code:\"binancecoin\" }\n  ],\n  stock: [\n    { name:\"贵州茅台\", code:\"sh600519\" },\n    { name:\"宁德时代\", code:\"sz300750\" },\n    { name:\"招商银行\", code:\"sh600036\" },\n    { name:\"苹果\",     code:\"usAAPL\" },\n    { name:\"腾讯控股\", code:\"hk00700\" }\n  ],\n  gold: [\n    { name:\"黄金\", code:\"pax-gold\" }\n  ],\n  goods: [\n    { name:\"大米\",   price:\"6\" },\n    { name:\"食用油\", price:\"79\" },\n    { name:\"纸巾\",   price:\"4\" },\n    { name:\"手机\",   price:\"4999\" },\n    { name:\"电脑\",   price:\"6999\" },\n    { name:\"自行车\", price:\"1200\" }\n  ]\n};\nfunction renderAssetQuick(){\n  const kind = assetKindSel;\n  $(\"#assetQuick\").innerHTML = ASSET_PRESETS[kind].map(p =>\n    '<button data-name=\"' + p.name + '\" data-code=\"' + (p.code || \"\") + '\" data-price=\"' + (p.price || \"\") + '\">' + p.name + \"<\/button>\"\n  ).join(\"\");\n  $(\"#assetCode\").style.display = (kind === \"gold\" || kind === \"goods\") ? \"none\" : \"\";\n  $(\"#assetCode\").placeholder = (kind === \"stock\")\n    ? \"代码：sh600519 / sz000001 / usAAPL / hk00700\"\n    : \"代码（如 bitcoin / ethereum / solana）\";\n  $(\"#assetPrice\").style.display = (kind === \"goods\") ? \"\" : \"none\";\n  $(\"#assetUnit\").style.display = (kind === \"goods\") ? \"\" : \"none\";\n  $(\"#assetConfirm\").textContent = (kind === \"goods\") ? \"添加\" : \"添加并获取实时行情\";\n}\nfunction openAssetForm(){\n  assetKindSel = \"crypto\";\n  document.querySelectorAll(\"#assetKind button\").forEach(x => x.classList.toggle(\"on\", x.dataset.k === \"crypto\"));\n  $(\"#assetName\").value = \"\"; $(\"#assetCode\").value = \"\"; $(\"#assetQty\").value = \"\";\n  $(\"#assetPrice\").value = \"\"; $(\"#assetUnit\").value = \"\";\n  renderAssetQuick();\n  openSheet($(\"#sheetAsset\"));\n}\n$(\"#assetKind\").addEventListener(\"click\", e => {\n  const b = e.target.closest(\"button\");\n  if(!b) return;\n  assetKindSel = b.dataset.k;\n  document.querySelectorAll(\"#assetKind button\").forEach(x => x.classList.toggle(\"on\", x === b));\n  renderAssetQuick();\n});\n$(\"#assetQuick\").addEventListener(\"click\", e => {\n  const b = e.target.closest(\"button\");\n  if(!b) return;\n  $(\"#assetName\").value = b.dataset.name || \"\";\n  if(b.dataset.code) $(\"#assetCode\").value = b.dataset.code;\n  if(b.dataset.price) $(\"#assetPrice\").value = b.dataset.price;\n  $(\"#assetQty\").focus();\n});\n$(\"#assetConfirm\").addEventListener(\"click\", () => {\n  const name = $(\"#assetName\").value.trim();\n  let code = $(\"#assetCode\").value.trim();\n  const qty = parseFloat(String($(\"#assetQty\").value).replace(/[^\\d.]/g, \"\"));\n  if(assetKindSel === \"gold\") code = \"pax-gold\";\n  if(!name){ toast(\"请填写名称\"); return; }\n  if(assetKindSel === \"stock\" && !/^(sh|sz|us|hk)[a-z0-9.]+$/i.test(code)){\n    toast(\"代码格式：sh600519 / sz000001 / usAAPL / hk00700\"); return;\n  }\n  if(assetKindSel === \"crypto\" && !code){ toast(\"请填写代码，如 bitcoin\"); return; }\n  if(!isFinite(qty) || qty <= 0){ toast(\"请填写有效数量\"); return; }\n\n  if(assetKindSel === \"goods\"){\n    const price = parseFloat(String($(\"#assetPrice\").value).replace(/[^\\d.]/g, \"\"));\n    if(!isFinite(price) || price <= 0){ toast(\"请填写单价\"); return; }\n    S.assets.push({\n      id: \"as\" + Date.now() + Math.random().toString(36).slice(2, 5),\n      kind: \"goods\", name: name, code: \"\",\n      qty: qty, price: price, unit: $(\"#assetUnit\").value.trim() || \"件\",\n      t: Date.now()\n    });\n    save();\n    curDim = \"assets\";\n    closeSheets();\n    renderAll();\n    toast(\"已添加 \" + name);\n    return;\n  }\n\n  S.assets.push({\n    id: \"as\" + Date.now() + Math.random().toString(36).slice(2, 5),\n    kind: assetKindSel, name: name, code: code.toLowerCase(),\n    qty: qty, price: 0, t: 0\n  });\n  save();\n  curDim = \"assets\";\n  closeSheets();\n  renderAll();\n  syncQuotes(true);\n});\n\n/* 自动同步：默认 15 分钟一次 */\nsetInterval(() => {\n  const gap = (S.syncMin || 15) * 60e3;\n  if(S.assets.length && !document.hidden && Date.now() - (S.lastSync || 0) > gap){\n    syncQuotes(false);\n  }\n}, 30e3);\n/* ============ 设置 ============ */\nfunction openSettings(){\n  refreshDiag();\n  document.querySelectorAll(\"#colorMode button\").forEach(b => {\n    b.classList.toggle(\"on\", b.dataset.c === S.colorMode);\n  });\n  document.querySelectorAll(\"#syncMode button\").forEach(b => {\n    b.classList.toggle(\"on\", Number(b.dataset.s) === (S.syncMin || 15));\n  });\n  $(\"#tgtWealth\").value = S.targets.wealth || \"\";\n  $(\"#tgtGrowth\").value = S.targets.growth || \"\";\n  $(\"#tgtScore\").value = S.targets.mood || \"\";\n  $(\"#updUrl\").value = S.updateUrl || \"\";\n  $(\"#verText\").textContent = APP_VERSION;\n$(\"#brandVer\").textContent = \"v\" + APP_VERSION;\n  const pend = localStorage.getItem(\"upd_ver\");\n  $(\"#updStatus\").textContent = (pend && cmpVer(pend, APP_VERSION) > 0)\n    ? (\"v\" + pend + \" 已下载 · 重启应用生效\") : (\"当前 v\" + APP_VERSION);  openSheet(sheetSet);\n}\n$(\"#btnSettings\").addEventListener(\"click\", openSettings);\n\n$(\"#updUrl\").addEventListener(\"change\", () => {\n  S.updateUrl = $(\"#updUrl\").value.trim();\n  save();\n});\n$(\"#btnCheckUpd\").addEventListener(\"click\", () => {\n  S.updateUrl = $(\"#updUrl\").value.trim();\n  save();\n  checkUpdate(true);\n});\n\n$(\"#syncMode\").addEventListener(\"click\", e => {\n  const b = e.target.closest(\"button\");\n  if(!b) return;\n  S.syncMin = Number(b.dataset.s) || 15;\n  document.querySelectorAll(\"#syncMode button\").forEach(x => x.classList.toggle(\"on\", x === b));\n  save();\n  toast(\"行情每 \" + S.syncMin + \" 分钟自动更新\");\n});\n\n$(\"#colorMode\").addEventListener(\"click\", e => {\n  const b = e.target.closest(\"button\");\n  if(!b) return;\n  S.colorMode = b.dataset.c;\n  document.querySelectorAll(\"#colorMode button\").forEach(x => x.classList.toggle(\"on\", x === b));\n  save();\n  renderAll();\n});\n\nfunction bindTarget(input, keys){\n  input.addEventListener(\"change\", () => {\n    const v = parseFloat(String(input.value).replace(/[^\\d.]/g, \"\"));\n    if(isFinite(v) && v > 0){\n      keys.forEach(k => { S.targets[k] = v; });\n      save();\n      renderAll();\n      toast(\"目标已更新\");\n    }\n  });\n}\nbindTarget($(\"#tgtWealth\"), [\"wealth\"]);\nbindTarget($(\"#tgtGrowth\"), [\"growth\"]);\nbindTarget($(\"#tgtScore\"), [\"mood\", \"health\"]);\n\n/* ============ 板块清零：每个板块单独清空，不影响其他板块 ============ */\n(function(){\n  const box = $(\"#dimClear\");\n  box.innerHTML = DIMS.map(d =>\n    '<button data-d=\"' + d.key + '\" style=\"font-size:11px;padding:0 12px;height:30px;border-radius:7px;border:1px solid #232a31;background:#0f1215;color:var(--text2);\">' + d.name + '<\/button>'\n  ).join(\"\");\n  box.addEventListener(\"click\", e => {\n    const b = e.target.closest(\"button[data-d]\");\n    if(!b) return;\n    const d = b.dataset.d;\n    const info = DIMS.find(x => x.key === d) || { name: d };\n    if(!confirm(\"确定清空「\" + info.name + \"」板块的全部记录吗？此操作不可恢复。\")) return;\n    S.entries = S.entries.filter(en => (en.dim || \"wealth\") !== d);\n    if(d === \"assets\") S.assets = [];\n    delete simStore[d];                      /* 该板块的横盘数据一并清除 */\n    save();\n    if(sim.on && sim.dim === d) simStart();  /* 若横盘正在该板块上跑，重新起锚 */\n    rebuild();\n    renderAll();\n    toast(\"「\" + info.name + \"」已清零\");\n  });\n})();\n\n$(\"#btnResetAll\").addEventListener(\"click\", () => {\n  if(!confirm(\"重置将清空全部记录、持仓与成就，然后可设定新的起点身价。确定吗？\")) return;\n  S.entries = []; S.assets = []; S.achievements = []; S.lastSync = 0; S.seeded = true;\n  save();\n  simStopAll(); clearTimeout(idleTimer);\n  closeSheets();\n  curDim = \"wealth\"; gran = \"day\";\n  view.shift = 0; view.count = 46;\n  renderAll();\n  toast(\"已重置，设定新的起点吧\");\n  setTimeout(() => openEdit(\"set\", \"wealth\"), 420);\n});\n\n$(\"#btnRestore\").addEventListener(\"click\", restoreFromBackup);\n\n/* ---- 诊断信息：远程排查用 ---- */\nfunction buildDiag(){\n  const st = simStore[curDim];\n  return [\n    \"版本 v\" + APP_VERSION,\n    \"板块 \" + curDim + \" (\" + dim().kind + \")\",\n    \"顶部原文 \" + $(\"#heroValue\").textContent.trim(),\n    \"期望值 \" + (function(){ try { const w = heroWant(); return w.empty ? \"(空)\" : w.v; } catch(e){ return \"ERR:\" + e.message; } })(),\n    \"横盘 \" + (sim.on ? sim.dim + \" base=\" + (st ? st.base : \"-\") + \" cur=\" + (st ? st.cur : \"-\") + \" ticks=\" + (st ? st.ticks.length : 0) : \"off\"),\n    \"K线数 \" + candles.length + \" / 记录数 \" + S.entries.length,\n    \"更新于 \" + new Date().toLocaleTimeString(\"zh-CN\", { hour12: false })\n  ].join(\"\\n\");\n}\nfunction refreshDiag(){\n  const el = $(\"#diagText\");\n  if(!el) return;\n  el.textContent = buildDiag();\n}\n$(\"#btnDiag\").addEventListener(\"click\", () => {\n  refreshDiag();\n  const txt = buildDiag();\n  const done = () => toast(\"诊断已复制，发给开发者即可\");\n  if(navigator.clipboard && navigator.clipboard.writeText){\n    navigator.clipboard.writeText(txt).then(done, () => { fallbackCopy(txt); done(); });\n  } else { fallbackCopy(txt); done(); }\n});\nfunction fallbackCopy(t){\n  const ta = document.createElement(\"textarea\");\n  ta.value = t; ta.style.position = \"fixed\"; ta.style.opacity = \"0\";\n  document.body.appendChild(ta); ta.select();\n  try { document.execCommand(\"copy\"); } catch(e){}\n  document.body.removeChild(ta);\n}\n\n$(\"#btnExport\").addEventListener(\"click\", () => {\n  const blob = new Blob([JSON.stringify(S, null, 2)], { type:\"application/json\" });\n  const a = document.createElement(\"a\");\n  a.href = URL.createObjectURL(blob);\n  a.download = \"life-ledger-\" + dayKey(Date.now()) + \".json\";\n  a.click();\n  setTimeout(() => URL.revokeObjectURL(a.href), 4000);\n  toast(\"已导出备份\");\n});\n\n$(\"#btnImport\").addEventListener(\"click\", () => $(\"#fileImport\").click());\n$(\"#fileImport\").addEventListener(\"change\", ev => {\n  const f = ev.target.files && ev.target.files[0];\n  if(!f) return;\n  const reader = new FileReader();\n  reader.onload = () => {\n    try {\n      const o = JSON.parse(reader.result);\n      if(!o || !Array.isArray(o.entries)) throw new Error(\"bad\");\n      S.entries = o.entries.map(e => ({\n        id: e.id || (\"i\" + Math.random().toString(36).slice(2, 9)),\n        t: e.t, mode: e.mode || \"delta\",\n        amount: Number(e.amount) || 0, note: e.note || \"\",\n        dim: e.dim || \"wealth\"\n      }));\n      S.targets = Object.assign(S.targets, o.targets || {});\n      S.assets = Array.isArray(o.assets) ? o.assets : [];\n      S.lastSync = o.lastSync || 0;\n      S.usdCny = o.usdCny || S.usdCny;\n      S.achievements = o.achievements || [];\n      S.seeded = true;\n      save();\n      renderAll();\n      closeSheets();\n      toast(\"导入成功，共 \" + S.entries.length + \" 条\");\n    } catch(err){\n      toast(\"文件格式不对\");\n    }\n  };\n  reader.readAsText(f);\n  ev.target.value = \"\";\n});\n\n$(\"#btnClearDemo\").addEventListener(\"click\", () => {\n  if(!confirm(\"将清空当前所有记录（含演示数据），从零开始。确定吗？\")) return;\n  S.entries = []; S.seeded = true; S.achievements = [];\n  save(); closeSheets(); renderAll();\n  toast(\"已清空，开始记录吧\");\n});\n\n$(\"#btnClearAll\").addEventListener(\"click\", () => {\n  if(!confirm(\"这会删除全部记录，且无法恢复。确定吗？\")) return;\n  S.entries = []; S.seeded = true; S.achievements = [];\n  save(); closeSheets(); renderAll();\n  toast(\"已清空全部记录\");\n});\n\n/* ============ 启动 ============ */\nload();\nconst hashDim = (location.hash || \"\").replace(\"#\", \"\").trim();\nif(DMAP[hashDim]) curDim = hashDim;\nview.count = PMAP[gran] ? PMAP[gran].count : 46;\nsyncColors();\nrebuild();\nrenderAll();\n\nif(window.ResizeObserver){\n  new ResizeObserver(() => resize()).observe(wrap);\n} else {\n  window.addEventListener(\"resize\", resize);\n}\nrequestAnimationFrame(resize);\nwindow.addEventListener(\"orientationchange\", () => setTimeout(resize, 220));\nresetIdle();\n\n/* 版本号显示 + 启动时静默检查应用内更新 */\n$(\"#verText\").textContent = APP_VERSION;\n$(\"#brandVer\").textContent = \"v\" + APP_VERSION;\nsetTimeout(() => {\n  checkUpdate(false);\n}, 2600);\n\n/* 启动时若持仓行情已过期，自动刷新 */\nsetTimeout(() => {\n  if(S.assets.length && Date.now() - (S.lastSync || 0) > (S.syncMin || 15) * 60e3 && !document.hidden){\n    syncQuotes(false);\n  }\n}, 1500);\n\nsetTimeout(() => {\n  const first = S.entries[0];\n  if(first && String(first.id).charAt(0) === \"d\"){\n    toast(\"当前是演示数据 · 设置里可清空\");\n  }\n}, 900);\n\nsetTimeout(() => {\n  toast(\"长按 K 线可查看任意一天的数据\");\n}, 2800);\n\n})();\n<\/script>\n<\/body>\n<\/html>\n"};
